// 產生檔：node tools/build_course_v2.js（來源 tools/content/course_v2/）。不要手改。
window.BUZZ_COURSE_V2_LESSONS = Object.assign(window.BUZZ_COURSE_V2_LESSONS || {}, {"sequence-limit":{"id":"sequence-limit","prerequisites":["limit-at-infinity","squeeze-theorem"],"next":["monotone-bounded"],"related":["lhopital","epsilon-n-definition","limit-e-type"],"objectives":["把數列看成只在正整數上取值的函數，說出 lim aₙ = L 的意思。","用代數化簡、借函數極限（含 L'Hôpital）、夾擠三種方法求數列極限。","記住 rⁿ 的收斂範圍與 ln n ≪ nᵖ ≪ bⁿ ≪ n! ≪ nⁿ 的增長順序。"],"concept":[{"heading":"① 數列是一串點","body":["數列 a₁, a₂, a₃, … 是只在正整數上有定義的函數：aₙ = f(n)。畫出來不是一條曲線，而是一顆一顆的點。","lim_{n→∞} aₙ = L 的意思是：n 夠大以後，aₙ 能要多靠近 L 就多靠近 L。這時說數列收斂到 L；不收斂就叫發散（可能往 ∞ 跑，也可能一直跳）。精確的寫法在〈ε-N 定義〉。"]},{"heading":"② 借用函數的極限","body":["如果 lim_{x→∞} f(x) = L，而 aₙ = f(n)，那麼 aₙ → L：函數在所有大 x 都靠近 L，整數點當然也是。這讓我們可以對 f(x) 用〈L'Hôpital 法則〉，再把結論搬回數列。","反過來不成立：aₙ = sin(πn) 每一項都是 0，極限是 0；但 sin(πx) 在 x → ∞ 時一直振盪、沒有極限。數列只看整數點。"]},{"heading":"③ 三個要記的結果","body":["rⁿ：|r| < 1 時 → 0；r = 1 時恆為 1；r > 1 時 → ∞；r ≤ −1 時正負跳動，發散。所以 rⁿ 收斂的充要條件是 −1 < r ≤ 1。","夾擠：bₙ ≤ aₙ ≤ cₙ 而兩邊收斂到同一個 L，aₙ 也 → L（〈夾擠定理〉的數列版）。例如 |cos n / n| ≤ 1/n → 0。","增長速度：ln n ≪ nᵖ（p > 0）≪ bⁿ（b > 1）≪ n! ≪ nⁿ。「≪」的意思是左邊除以右邊 → 0。"]}],"workedExamples":[{"title":"有理式：同除最高次","prompt":"lim_{n→∞} (3n² + n)/(n² + 2)","problemId":"cx-seq-001","steps":["分子分母同除以 n²：(3 + 1/n)/(1 + 2/n²)。","n → ∞ 時 1/n → 0、2/n² → 0，極限 = 3/1 = 3。"],"answer":"3"},{"title":"借函數用 L'Hôpital","prompt":"lim_{n→∞} (ln n)/n","problemId":"lec-11-q1b","steps":["L'Hôpital 只能對可微函數用，不能直接對 n 微分。改看 f(x) = (ln x)/x，x → ∞ 時是 ∞/∞。","lim_{x→∞} (ln x)/x = lim_{x→∞} (1/x)/1 = 0。","aₙ = f(n)，所以 lim (ln n)/n = 0。這也是「ln n ≪ n」的一個證明。"],"answer":"0"},{"title":"夾擠","prompt":"lim_{n→∞} (3ⁿ + 4ⁿ)^{1/n}","problemId":"lec-11-q1d","steps":["最大的一項是 4ⁿ：4ⁿ ≤ 3ⁿ + 4ⁿ ≤ 4ⁿ + 4ⁿ = 2 · 4ⁿ。","三邊開 n 次方（都是正數，開方保持大小順序）：4 ≤ (3ⁿ + 4ⁿ)^{1/n} ≤ 2^{1/n} · 4。","2^{1/n} = e^{(ln 2)/n} → e⁰ = 1，右邊 → 4。由夾擠，極限是 4。"],"answer":"4"}],"pitfalls":["直接對 n 微分用 L'Hôpital：要先換成連續變數 x 的函數。","以為函數 f(x) 沒有極限，數列 f(n) 也一定沒有。","把 rⁿ 的收斂範圍寫成 |r| < 1，漏了 r = 1。","看到 cos n、sin n 就說發散，沒想到分母可能把它壓到 0。"],"checks":[{"ask":"數列 rⁿ 收斂的充要條件是？","options":[{"label":"−1 < r ≤ 1","correct":true},{"label":"|r| < 1","why":"漏了 r = 1：1ⁿ 每一項都是 1，收斂到 1。"},{"label":"−1 ≤ r ≤ 1","why":"r = −1 時 (−1)ⁿ 在 −1 與 1 之間跳，不收斂。"}]},{"ask":"aₙ = sin(πn)，lim aₙ 是？","options":[{"label":"0","correct":true},{"label":"不存在，因為 sin(πx) 在 x → ∞ 沒有極限","why":"數列只看整數點；n 是整數時 sin(πn) 全是 0。函數沒有極限，不代表數列沒有。"},{"label":"1","why":"sin 在 π 的整數倍都是 0，不是 1。"}]},{"ask":"n → ∞ 時，由慢到快的增長順序是？","options":[{"label":"ln n、n²、2ⁿ、n!","correct":true},{"label":"ln n、2ⁿ、n²、n!","why":"前幾項 n² 比較大，但指數最終一定贏過多項式：n = 10 時 2¹⁰ = 1024 已經超過 100。"},{"label":"n²、ln n、2ⁿ、n!","why":"對數長得比任何正次方都慢：(ln n)/n² → 0。"}]},{"ask":"lim_{n→∞} (cos n)/n 是？","options":[{"label":"0","correct":true},{"label":"不存在，因為 cos n 一直振盪","why":"分子雖然振盪，但被 −1 與 1 夾住；−1/n ≤ (cos n)/n ≤ 1/n，兩邊都 → 0。"},{"label":"1","why":"cos n 沒有趨近 1；而且分母 n → ∞，整個分式會被壓到 0。"}]}],"practice":[{"id":"lec-11-m1","core":true},{"id":"cx-seq-001","core":true},{"id":"lec-11-q1b","core":true},{"id":"lec-11-q2a","core":true},{"id":"lec-11-q1d","core":true},{"id":"lec-11-q1a"},{"id":"cx-seq-006"},{"id":"lec-11-q1c"},{"id":"lec-11-m3"},{"id":"lec-11-m2"},{"id":"lec-11-q2d"}]},"monotone-bounded":{"id":"monotone-bounded","prerequisites":["sequence-limit","increasing-decreasing"],"next":["monotone-convergence-sequence"],"related":["bounds"],"objectives":["說出遞增、遞減、有上界、有下界、有界的定義，以及「從某一項開始」的意思。","用差、比值、導數三種方法判斷數列的單調性。","分清楚有界與收斂：收斂一定有界，有界不一定收斂。"],"concept":[{"heading":"① 定義","body":["遞增：對所有 n，aₙ₊₁ ≥ aₙ（嚴格遞增是 >）。遞減：aₙ₊₁ ≤ aₙ。兩者之一叫單調。","有上界：存在 M 使所有 aₙ ≤ M。有下界：存在 m 使所有 aₙ ≥ m。兩個都有叫有界。","討論極限時，前面有限項怎麼亂跳都不影響，所以常說「從某一項開始遞減」（最終遞減）就夠了。"]},{"heading":"② 判斷單調的三個方法","body":["差：看 aₙ₊₁ − aₙ 的正負。適合有理式。","比值：各項都是正數時，看 aₙ₊₁/aₙ 跟 1 比。適合有 2ⁿ、n! 的式子，因為會大量約分。","導數：如果 aₙ = f(n)，而 f′(x) ≤ 0 在 x ≥ N 上成立，數列從第 N 項開始遞減（〈增減區間〉）。適合有 ln、根號的式子。注意 n! 不能這樣微分。"]},{"heading":"③ 有界與收斂","body":["收斂的數列一定有界：n 夠大後 aₙ 都在 L ± 1 裡，前面只剩有限項，取它們和 L ± 1 中最大、最小的就是界。","反過來不行：(−1)ⁿ 有界但在 −1 與 1 之間跳，不收斂。單調也不夠：aₙ = n 遞增但跑到 ∞。下一課〈單調收斂定理〉說的是：兩個條件同時成立，就一定收斂。"]}],"workedExamples":[{"title":"用差","prompt":"aₙ = n/(n + 1)。判斷單調性與有界性。","steps":["aₙ₊₁ − aₙ = (n + 1)/(n + 2) − n/(n + 1) = ((n + 1)² − n(n + 2))/((n + 1)(n + 2)) = 1/((n + 1)(n + 2)) > 0。嚴格遞增。","0 < n/(n + 1) < 1 對所有 n 成立（分子比分母小 1）。有界。"],"answer":"嚴格遞增，0 < aₙ < 1"},{"title":"用比值","prompt":"aₙ = n/2ⁿ。判斷單調性與有界性。","steps":["各項為正，算比值：aₙ₊₁/aₙ = ((n + 1)/2ⁿ⁺¹) · (2ⁿ/n) = (n + 1)/(2n)。","(n + 1)/(2n) ≤ 1 ⇔ n + 1 ≤ 2n ⇔ n ≥ 1。等號只在 n = 1：a₁ = a₂ = 1/2，之後嚴格遞減。","所以數列遞減（非嚴格），0 < aₙ ≤ 1/2，有界。"],"answer":"遞減，0 < aₙ ≤ 1/2"},{"title":"用導數：最終遞減","prompt":"aₙ = (ln n)/n。從哪一項開始遞減？","steps":["令 f(x) = (ln x)/x，f′(x) = (1 − ln x)/x²。x > e 時 ln x > 1，f′ < 0。","e ≈ 2.718，所以從 n = 3 開始遞減。","看前幾項確認：a₁ = 0、a₂ ≈ 0.347、a₃ ≈ 0.366、a₄ ≈ 0.347。先升後降，最大值是 a₃。"],"answer":"從 n = 3 開始遞減"}],"pitfalls":["只看前兩三項就判斷單調：(ln n)/n 前面升、後面降。","對含 n! 的數列微分：n! 不是可微函數，要用比值。","比值法用在有負項的數列上：比值跟 1 比只對正項有意義。","以為有界就收斂，或以為單調就收斂。"],"checks":[{"ask":"aₙ = (−1)ⁿ/n 是？","options":[{"label":"不單調，有界","correct":true},{"label":"遞減，有界","why":"正負交替：a₁ = −1、a₂ = 1/2、a₃ = −1/3，一下往上一下往下。"},{"label":"不單調，無界","why":"|aₙ| = 1/n ≤ 1，所有項都在 −1 與 1/2 之間。"}]},{"ask":"判斷 aₙ = 3ⁿ/n! 的單調性，最省事的方法是？","options":[{"label":"比值 aₙ₊₁/aₙ","correct":true},{"label":"對 f(x) = 3ˣ/x! 微分","why":"x! 對非整數沒有定義，不能這樣微分。"},{"label":"只算前三項看趨勢","why":"a₁ = 3、a₂ = 4.5、a₃ = 4.5，看前三項會以為遞增；比值 3/(n + 1) 才看得出 n ≥ 3 開始遞減。"}]},{"ask":"有界的數列一定收斂嗎？","options":[{"label":"不一定，例如 (−1)ⁿ","correct":true},{"label":"一定收斂","why":"(−1)ⁿ 被 ±1 夾住，卻一直在兩個值之間跳，沒有極限。"},{"label":"一定發散","why":"1/n 有界而且收斂到 0。有界本身不決定收斂或發散。"}]},{"ask":"aₙ = n/(n + 1) 是？","options":[{"label":"遞增，有上界 1","correct":true},{"label":"遞減，有下界 0","why":"aₙ₊₁ − aₙ = 1/((n + 1)(n + 2)) > 0，是遞增。"},{"label":"遞增，沒有上界","why":"分子永遠比分母小 1，aₙ < 1。"}]}],"practice":[{"id":"lec-11-q3b","core":true,"note":"用 aₙ₊₁² − aₙ² 的正負判斷遞增；平方的差比根號的差好處理。"}]},"monotone-convergence-sequence":{"id":"monotone-convergence-sequence","prerequisites":["monotone-bounded"],"next":["recursive-sequence"],"related":["completeness-axiom","monotone-convergence-proof","basel-problem","limit-e-type","partial-sums"],"objectives":["說出單調收斂定理：遞增且有上界（或遞減且有下界）的數列必收斂。","用它證明極限存在，並分清楚「存在」與「等於多少」是兩件事。","知道正項級數的部分和是遞增數列，只要有界就收斂。"],"concept":[{"heading":"① 定理","body":["若數列 aₙ 遞增且有上界，則 aₙ 收斂；若遞減且有下界，也收斂。（「從某一項開始」單調也可以。）"]},{"heading":"② 為什麼會對：直觀，不是證明","body":["一直往上走、又不能穿過天花板 M，走的步伐只能越來越小，最後擠在某個高度附近。","這個說明漏了一件事：那個「某個高度」真的存在嗎？在有理數裡就不一定。1、1.4、1.41、1.414、… 每一項都是有理數，遞增、小於 1.5，可是它擠向的是 √2，不是有理數。實數不會有這種空洞，這正是〈完備性公理〉；用它寫成的嚴格證明在〈單調收斂定理（嚴格版）〉，極限就是這串數的最小上界。"]},{"heading":"③ 它給你什麼、不給你什麼","body":["定理只保證極限存在，不告訴你極限是多少。值要用別的方法算：解方程（〈遞迴數列〉）、夾擠，或者乾脆把這個極限當成定義。e 就是這樣定義的（〈e 型極限〉）。","兩個條件少一個都不行：aₙ = n 遞增但沒有上界，(−1)ⁿ 有界但不單調，兩者都發散。"]},{"heading":"④ 通往級數的橋","body":["各項為正的級數，部分和 sₙ = a₁ + … + aₙ 每次都加一個正數，一定遞增（〈部分和〉）。所以正項級數收斂 ⇔ 部分和有上界。後面所有正項級數的判別法，本質上都在證明「有界」或「無界」。"]}],"workedExamples":[{"title":"部分和有界","prompt":"證明 sₙ = Σ_{k=1}^{n} 1/k² 收斂。","steps":["每次加 1/(n + 1)² > 0，sₙ 遞增。","找上界：k ≥ 2 時 1/k² < 1/(k(k − 1)) = 1/(k − 1) − 1/k。","所以 sₙ < 1 + (1 − 1/2) + (1/2 − 1/3) + … + (1/(n − 1) − 1/n) = 1 + 1 − 1/n < 2。","遞增且有上界 2，由單調收斂定理，sₙ 收斂。極限其實是 π²/6 ≈ 1.645（〈Basel 問題〉），但這個值不是這個定理給的。"],"answer":"收斂（極限 ≤ 2）"},{"title":"定義 e 的那個數列","prompt":"aₙ = (1 + 1/n)ⁿ。證明它遞增且有上界 3。","steps":["遞增：對 n 個 (1 + 1/n) 與一個 1 這 n + 1 個正數用算幾不等式，幾何平均 ≤ 算術平均：((1 + 1/n)ⁿ · 1)^{1/(n+1)} ≤ (n(1 + 1/n) + 1)/(n + 1) = 1 + 1/(n + 1)。兩邊 n + 1 次方得 aₙ ≤ aₙ₊₁。","有界：二項式展開 (1 + 1/n)ⁿ = Σ_{k=0}^{n} C(n, k)/nᵏ，而 C(n, k)/nᵏ = (n(n − 1)…(n − k + 1)/nᵏ) · (1/k!) ≤ 1/k!。","k ≥ 1 時 k! ≥ 2^{k−1}，所以 aₙ ≤ 1 + (1 + 1/2 + 1/4 + … + 1/2^{n−1}) < 1 + 2 = 3（有限項的幾何和小於 2）。","遞增且有上界，aₙ 收斂。這個極限就叫做 e ≈ 2.718。"],"answer":"遞增、aₙ < 3，所以收斂（極限記為 e）"},{"title":"先證存在，再找值","prompt":"aₙ = n!/nⁿ。證明它收斂，並求極限。","steps":["比值：aₙ₊₁/aₙ = (n + 1)! nⁿ /((n + 1)ⁿ⁺¹ n!) = (n/(n + 1))ⁿ < 1，遞減。aₙ > 0，有下界 0。由定理，極限存在。","找值：aₙ = (1/n) · (2/n) ⋯ (n/n) ≤ 1/n，因為除了第一個因子，其餘都 ≤ 1。","0 < aₙ ≤ 1/n，夾擠得極限 0。"],"answer":"0"}],"pitfalls":["只驗證有界、沒驗證單調（或反過來）就說收斂。","以為定理給了極限值。","以為上界就是極限：1 − 1/n 有上界 5，極限是 1。","忘了「從某一項開始單調」也可以用，前面幾項不必理會。"],"checks":[{"ask":"單調收斂定理需要哪些條件？","options":[{"label":"單調，而且往前進的方向有界（遞增配上界、遞減配下界）","correct":true},{"label":"只要有界","why":"(−1)ⁿ 有界卻不收斂；少了單調，數列可以一直跳。"},{"label":"只要單調","why":"aₙ = n 遞增，但沒有上界，跑到 ∞。"}]},{"ask":"單調收斂定理告訴你？","options":[{"label":"極限存在","correct":true},{"label":"極限的值","why":"它只保證存在；值要另外算，例如解遞迴方程或夾擠。"},{"label":"數列最後會等於極限","why":"1 − 1/n 遞增收斂到 1，但沒有任何一項等於 1。"}]},{"ask":"aₙ 遞增且每一項都 ≤ 5，極限 L 滿足？","options":[{"label":"L ≤ 5","correct":true},{"label":"L = 5","why":"5 只是一個上界，不一定是最小的那個。1 − 1/n 也 ≤ 5，極限卻是 1。"},{"label":"L < 5","why":"可以剛好等於：5 − 1/n 遞增、都 ≤ 5，極限就是 5。"}]},{"ask":"1、1.4、1.41、1.414、…（√2 的小數截斷）說明了什麼？","options":[{"label":"只用有理數的話，遞增有界的數列可能沒有極限","correct":true},{"label":"定理在有理數裡也成立","why":"這串數擠向 √2，而 √2 不是有理數；在有理數裡它找不到可以收斂的對象。"},{"label":"這串數不是單調的","why":"每多一位小數，值只會變大或不變，它是遞增的。"}]}],"practice":[{"id":"lec-11-m5","core":true},{"id":"lec-11-q3c","core":true},{"id":"cx-seq-002"},{"id":"lec-12-q4a","challenge":true,"note":"挑戰：證明調和級數的部分和沒有上界，所以單調收斂定理不適用、它發散。"}]},"recursive-sequence":{"id":"recursive-sequence","prerequisites":["monotone-convergence-sequence"],"next":["infinite-series"],"related":["induction","continuity-definition"],"objectives":["照四個步驟處理 aₙ₊₁ = g(aₙ)：有界（歸納法）、單調、存在、解方程。","說明為什麼要先證極限存在，才能解 L = g(L)。","用數列的範圍篩掉方程多出來的根。"],"concept":[{"heading":"① 一項由前一項決定","body":["a₁ = √2，aₙ₊₁ = √(2 + aₙ)：先算幾項，1.4142、1.8478、1.9616、1.9904、1.9976……看起來往 2 靠。猜答案很容易：如果極限 L 存在，對 aₙ₊₁ = √(2 + aₙ) 兩邊取極限，L = √(2 + L)，解出 L = 2。","關鍵字是「如果極限存在」。"]},{"heading":"② 為什麼不能直接解方程","body":["a₁ = 1，aₙ₊₁ = 1 − aₙ：照抄上面的做法，L = 1 − L，L = 1/2。可是數列是 1, 0, 1, 0, …，根本不收斂。","a₁ = 1，aₙ₊₁ = 2aₙ：L = 2L 得 L = 0，但 aₙ = 2ⁿ⁻¹ → ∞。","方程 L = g(L) 的意思是「如果有極限，它只能是這些值之一」。極限存不存在，要另外證明。"]},{"heading":"③ 四個步驟","body":["1. 有界：用〈數學歸納法〉證明所有 aₙ 落在某個範圍裡。","2. 單調：看 aₙ₊₁ − aₙ（或平方差、比值）的正負，通常會用到第 1 步的範圍。","3. 存在：由〈單調收斂定理〉，極限 L 存在。","4. 求值：g 連續（〈連續的定義〉），對兩邊取極限得 L = g(L)。解出來若有好幾個根，用第 1 步的範圍挑出對的那個。"]}],"workedExamples":[{"title":"完整四步","prompt":"a₁ = √2，aₙ₊₁ = √(2 + aₙ)。求 lim aₙ。","problemId":"lec-11-q3c","steps":["有界：0 < a₁ < 2。若 0 < aₙ < 2，則 0 < aₙ₊₁ = √(2 + aₙ) < √4 = 2。由歸納法，所有 0 < aₙ < 2。","單調：aₙ₊₁² − aₙ² = 2 + aₙ − aₙ² = (2 − aₙ)(1 + aₙ)。由第 1 步兩個因子都正，所以 aₙ₊₁² > aₙ²；兩者都是正數，得 aₙ₊₁ > aₙ。遞增。","存在：遞增且有上界 2，極限 L 存在。","求值：√ 連續，L = √(2 + L)，L² − L − 2 = (L − 2)(L + 1) = 0。所有項都是正的，L ≥ 0，捨去 −1。L = 2。"],"answer":"2"},{"title":"牛頓法開根號：遞減的版本","prompt":"a₁ = 1，aₙ₊₁ = ½(aₙ + 2/aₙ)。求 lim aₙ。","problemId":"cx-seq-005","steps":["前幾項：1、1.5、1.41667、1.414216……","有下界：歸納可知 aₙ > 0。對任何 x > 0，½(x + 2/x) − √2 = (x − √2)²/(2x) ≥ 0，所以從第 2 項起 aₙ ≥ √2。","單調：n ≥ 2 時 aₙ₊₁ − aₙ = (2 − aₙ²)/(2aₙ) ≤ 0（因為 aₙ ≥ √2），遞減。","存在且求值：遞減有下界，極限 L 存在且 L ≥ √2。L = ½(L + 2/L) ⇒ L² = 2 ⇒ L = √2。"],"answer":"√2"},{"title":"反例：方程有解，數列卻發散","prompt":"a₁ = 1，aₙ₊₁ = 1 − aₙ。lim aₙ 是 1/2 嗎？","steps":["直接寫出各項：a₂ = 0，a₃ = 1，a₄ = 0，……奇數項都是 1，偶數項都是 0。","數列在 0 與 1 之間跳，不收斂。方程 L = 1 − L 的解 1/2 只是「如果有極限，它會是多少」，而極限不存在。","跟四步驟對照：數列有界（在 0 與 1 之間），但不單調，第 2 步過不了。"],"answer":"不是；數列發散"}],"pitfalls":["還沒證明極限存在就解 L = g(L)。","用「極限是 2」去證明「每一項都小於 2」：循環論證。","解出兩個根卻不篩選（例如留下 L = −1）。","只算前幾項就宣稱遞增，沒有對所有 n 證明。"],"checks":[{"ask":"為什麼要先證明極限存在，才解 L = g(L)？","options":[{"label":"L = g(L) 只說明「若極限存在，它必須滿足這個方程」","correct":true},{"label":"因為方程可能沒有解","why":"有解也沒用：aₙ₊₁ = 1 − aₙ 的方程有解 1/2，數列卻在 0、1 之間跳。"},{"label":"因為歸納法規定要這樣","why":"這跟歸納法無關，是邏輯順序：「對極限取極限」要先有極限。"}]},{"ask":"a₁ = √6，aₙ₊₁ = √(6 + aₙ)（已知遞增有界）。極限是？","options":[{"label":"3","correct":true},{"label":"−2","why":"L² − L − 6 = 0 的另一個根。每一項都是正的根號，極限不可能是負數。"},{"label":"3 或 −2","why":"數列只有一個極限；要用 aₙ > 0 把 −2 篩掉。"}]},{"ask":"要證明 aₙ₊₁ = √(2 + aₙ)（a₁ = √2）的每一項都 < 2，應該用？","options":[{"label":"數學歸納法","correct":true},{"label":"先算出極限是 2，所以每一項都 < 2","why":"循環論證：極限的存在本身就要用到有界；而且就算極限是 2，也推不出每一項都 < 2。"},{"label":"算前十項，都小於 2","why":"有限項的檢查涵蓋不了所有 n。"}]},{"ask":"a₁ = 1，aₙ₊₁ = 2aₙ。有人寫「L = 2L，所以 L = 0」。錯在哪？","options":[{"label":"aₙ = 2ⁿ⁻¹ → ∞，極限不存在","correct":true},{"label":"沒有錯，極限是 0","why":"各項 1, 2, 4, 8, … 越來越大，不可能靠近 0。"},{"label":"方程解錯了，應該是 L = 2","why":"L = 2L 的唯一解就是 0；問題不在解方程，而在極限根本不存在。"}]}],"practice":[{"id":"lec-11-q3a","core":true},{"id":"lec-11-q3b","core":true},{"id":"lm-rc-001","core":true},{"id":"cx-seq-004","core":true},{"id":"lm-rc-002","core":true},{"id":"lx-seq-001"},{"id":"lm-rc-004"},{"id":"an-ca-003"},{"id":"lm-rc-006"},{"id":"lx-seq-004"},{"id":"lm-rc-003","challenge":true,"note":"挑戰：這個數列不單調（1, 2, 1.5, 1.67, …），四步驟的第 2 步要改成奇數項、偶數項分開看。"},{"id":"lm-rc-007","challenge":true,"note":"挑戰：cos x = x 沒有公式解，答案是數值；而且數列忽大忽小，不是單調的。"}]},"infinite-series":{"id":"infinite-series","prerequisites":["sequence-limit"],"next":["partial-sums"],"related":["geometric-series","divergence-test","p-series"],"objectives":["說出 Σ aₙ 的定義：部分和 sₙ 的極限；有極限叫收斂，沒有叫發散。","分清楚兩個數列：各項 aₙ 與部分和 sₙ。","知道收斂級數可以逐項相加、乘常數，而去掉或加上有限項不影響收斂。"],"concept":[{"heading":"① 無窮多個數相加，到底是什麼意思","body":["沒有人能真的把無窮多個數一個個加完。所以先加有限項：sₙ = a₁ + a₂ + … + aₙ，叫做第 n 個部分和。再看 n → ∞ 時 sₙ 往哪裡去，定義 Σ aₙ = lim sₙ。","極限存在（是一個實數 S），就說級數收斂，和是 S，寫 Σ aₙ = S。極限不存在（跑到 ∞，或一直跳），就說級數發散。"],"tex":["\\sum_{n=1}^{\\infty} a_n=\\lim_{n\\to\\infty} s_n,\\qquad s_n=a_1+a_2+\\cdots+a_n"]},{"heading":"② 三種結局","body":["1/2 + 1/4 + 1/8 + …：部分和 1/2、3/4、7/8、…，是 1 − 1/2ⁿ → 1，收斂到 1（正方形那張圖）。","1 + 1 + 1 + …：sₙ = n → ∞，發散。","1 − 1 + 1 − 1 + …：sₙ 是 1、0、1、0、…，一直跳，發散。"]},{"heading":"③ 兩個數列，不要混在一起","body":["一個級數牽涉兩個數列：各項 aₙ，和部分和 sₙ。「級數收斂」說的是 sₙ 有極限，不是 aₙ。例如 1/2 + 1/4 + … 的各項 → 0，部分和 → 1。兩者的關係在〈發散判別〉細講。"]},{"heading":"④ 基本規則","body":["Σ aₙ 與 Σ bₙ 都收斂時，Σ(aₙ + bₙ) = Σ aₙ + Σ bₙ，Σ c·aₙ = c Σ aₙ。理由：部分和是有限和，可以這樣拆，再用極限定律。","去掉（或加上）前面有限多項，不改變收不收斂，因為部分和只差一個固定的數；但和會改變。所以 Σ_{n=1}^∞ 和 Σ_{n=5}^∞ 收斂與否相同，數值不同。"]}],"workedExamples":[{"title":"循環小數是一個級數","prompt":"0.333… 寫成級數，並求它的值。","steps":["0.333… = 3/10 + 3/100 + 3/1000 + … = Σ_{n=1}^∞ 3/10ⁿ。","部分和 sₙ = 0.33…3（n 個 3）。它和 1/3 差多少？1/3 − sₙ = (1/3)(1/10ⁿ)，所以 sₙ = (1/3)(1 − 10⁻ⁿ)。","n → ∞ 時 10⁻ⁿ → 0，sₙ → 1/3。"],"answer":"1/3"},{"title":"0.999… = 1","prompt":"Σ_{n=1}^∞ 9/10ⁿ = 0.999… 是多少？","steps":["每一項是範例 1 的 3 倍：9/10ⁿ = 3 · (3/10ⁿ)。","範例 1 的級數收斂，可以整個乘 3：Σ 9/10ⁿ = 3 · (1/3) = 1。","所以 0.999… = 1，不是「差一點點」。它是部分和 1 − 10⁻ⁿ 的極限，極限剛好是 1。"],"answer":"1"},{"title":"部分和一直跳","prompt":"1 − 1 + 1 − 1 + … 收斂嗎？","steps":["部分和：s₁ = 1，s₂ = 0，s₃ = 1，s₄ = 0，……一般式 sₙ = (1 − (−1)ⁿ)/2。","sₙ 在 1 與 0 之間來回，沒有極限，級數發散。","把它寫成 (1 − 1) + (1 − 1) + … = 0，或 1 − (1 − 1) − … = 1，都是偷偷改了級數本身：加括號後的部分和只是原本部分和的一部分。"],"answer":"發散"}],"pitfalls":["把「各項 → 0」當成「級數收斂」。","對發散的級數加括號，得到一個看起來合理的和。","以為 0.999… 比 1 小一點點。","去掉前幾項之後，以為和不變。"],"checks":[{"ask":"「Σ aₙ 收斂」的意思是？","options":[{"label":"部分和 sₙ 有極限","correct":true},{"label":"各項 aₙ → 0","why":"那說的是各項，不是部分和；之後會看到各項 → 0 而級數仍發散的例子。"},{"label":"從某一項開始，每一項都很小","why":"「很小」不是定義；Σ 1/n 的各項都很小，部分和卻沒有上界（〈p 級數〉會證明）。"}]},{"ask":"1 − 1 + 1 − 1 + … 是？","options":[{"label":"發散","correct":true},{"label":"0","why":"這是加了括號 (1 − 1) + (1 − 1) + … 得到的；原本的部分和在 1、0 之間跳，沒有極限。"},{"label":"1/2","why":"1/2 是部分和 1, 0, 1, 0 的平均，不是部分和的極限。"}]},{"ask":"0.999… 和 1 的關係是？","options":[{"label":"相等","correct":true},{"label":"0.999… 比 1 小一點點","why":"0.999… 指的是部分和 1 − 10⁻ⁿ 的極限，極限剛好是 1；「小一點點」說的是某個有限的部分和。"},{"label":"0.999… 沒有定義","why":"它就是 Σ 9/10ⁿ，部分和有極限，定義得很清楚。"}]},{"ask":"把一個收斂級數的前 100 項拿掉，剩下的級數？","options":[{"label":"還是收斂，但和改變","correct":true},{"label":"變成發散","why":"新的部分和等於舊的部分和減掉一個固定的數，極限照樣存在。"},{"label":"還是收斂，而且和不變","why":"和會少掉前 100 項的總和（除非那總和剛好是 0）。"}]}],"practice":[{"id":"lec-12-m1","core":true},{"id":"fd-ser-003","core":true},{"id":"lec-12-q1b","core":true},{"id":"fd-ser-005","core":true},{"id":"sg-est-006"},{"id":"lec-12-q1a"}]},"partial-sums":{"id":"partial-sums","prerequisites":["infinite-series"],"next":["geometric-series"],"related":["telescoping-series","alternating-series-test","integral-test","monotone-convergence-sequence"],"objectives":["會算前幾個部分和，也會找部分和 sₙ 的公式再取極限。","已知 sₙ 反推各項：a₁ = s₁，aₙ = sₙ − sₙ₋₁（n ≥ 2）。","知道用 s_N 估計級數和時，誤差是整條尾巴 Σ_{n>N} aₙ。"],"concept":[{"heading":"① 部分和是一個新的數列","body":["〈無窮級數〉把 Σ aₙ 定義成 lim sₙ。所以研究級數，常常就是研究 sₙ 這個數列：先算 s₁、s₂、s₃ 看趨勢，再想辦法寫出 sₙ 的公式，最後取極限。","能寫出公式的情況不多：等差、等比（〈幾何級數〉）、相消（〈望遠鏡級數〉）是三種主要的。寫不出公式時，要靠後面幾課的判別法：它們不算和，只判斷收不收斂。"]},{"heading":"② 從部分和反推各項","body":["sₙ − sₙ₋₁ = aₙ（多加的就是第 n 項），而 a₁ = s₁。題目直接給 sₙ 時，級數的和就是 lim sₙ，連各項都不必先求。"]},{"heading":"③ 部分和圖的兩種樣子","body":["各項都是正的：sₙ 每次加正數，一路往上（遞增）。它收斂 ⇔ 有上界（〈單調收斂定理〉）。","正負交替：sₙ 一上一下地跳。如果跳的幅度縮到 0，就會夾住一個極限（〈交錯級數判別〉）。"]},{"heading":"④ 用部分和估計級數和","body":["實際算級數和時，常常只能取前 N 項 s_N。誤差是還沒加的整條尾巴 R_N = S − s_N = Σ_{n=N+1}^∞ aₙ，不是最後一項，也不是下一項。尾巴有多大，要用〈積分判別〉或〈交錯級數判別〉的估計式才能保證。"]}],"workedExamples":[{"title":"給部分和，求各項與和","prompt":"某級數的部分和 sₙ = n/(n + 1)。求 aₙ 與級數和。","steps":["a₁ = s₁ = 1/2。","n ≥ 2：aₙ = n/(n + 1) − (n − 1)/n = (n² − (n² − 1))/(n(n + 1)) = 1/(n(n + 1))。n = 1 代進去也是 1/2，所以這個公式對所有 n 都成立。","和 = lim sₙ = lim n/(n + 1) = 1。"],"answer":"aₙ = 1/(n(n + 1))，和為 1"},{"title":"算前幾個部分和","prompt":"交錯調和級數 1 − 1/2 + 1/3 − 1/4 + …，求 S₁ 到 S₆。","problemId":"sg-est-001","steps":["S₁ = 1，S₂ = 1/2，S₃ = 5/6 ≈ 0.833，S₄ = 7/12 ≈ 0.583。","S₅ = 7/12 + 1/5 = 47/60 ≈ 0.783，S₆ = 47/60 − 1/6 = 37/60 ≈ 0.617。","奇數項的部分和往下、偶數項的往上，兩邊夾向同一個數；這個級數的和其實是 ln 2 ≈ 0.693。"],"answer":"S₆ = 37/60"},{"title":"部分和公式顯示發散","prompt":"1 + 3 + 5 + 7 + …（奇數相加）。求 sₙ，並判斷收斂與否。","problemId":"fd-ser-018","steps":["等差數列求和：sₙ = n(首項 + 末項)/2 = n(1 + (2n − 1))/2 = n²。例如 s₆ = 36。","反推檢查：sₙ − sₙ₋₁ = n² − (n − 1)² = 2n − 1，正是第 n 個奇數。","sₙ = n² → ∞，級數發散。"],"answer":"sₙ = n²，發散"}],"pitfalls":["把 sₙ 當成 aₙ，或把 aₙ 的極限當成級數和。","反推 aₙ = sₙ − sₙ₋₁ 時忘了單獨處理 a₁。","估計誤差時只看最後一項或下一項，忽略整條尾巴。","只看前幾個部分和就下結論：要看 sₙ 在 n → ∞ 的行為。"],"checks":[{"ask":"某級數的部分和 sₙ = 5 − 2/n。級數的和是？","options":[{"label":"5","correct":true},{"label":"3","why":"3 是 s₁ = 5 − 2；級數的和是 n → ∞ 時 sₙ 的極限。"},{"label":"發散","why":"2/n → 0，sₙ → 5，有極限。"}]},{"ask":"某級數的部分和 sₙ = n²。第 n 項 aₙ 是？","options":[{"label":"2n − 1","correct":true},{"label":"n²","why":"那是部分和；第 n 項是 sₙ − sₙ₋₁。"},{"label":"2n","why":"n² − (n − 1)² = n² − (n² − 2n + 1) = 2n − 1；展開時漏了 −1。"}]},{"ask":"各項都是正數的級數，部分和 sₙ 一定？","options":[{"label":"遞增","correct":true},{"label":"一上一下地跳","why":"每次都加正數，sₙ 只會往上；會跳的是正負交替的級數。"},{"label":"遞減","why":"加上正數只會變大。"}]},{"ask":"用前 N 項的和 s_N 估計級數和 S，誤差 S − s_N 是？","options":[{"label":"Σ_{n=N+1}^∞ aₙ","correct":true},{"label":"a_N","why":"a_N 已經加進 s_N 了；誤差是還沒加的所有項。"},{"label":"a_{N+1}","why":"這只是下一項，後面還有無窮多項。下一項只在某些情況下（交錯級數）是誤差的上界。"}]}],"practice":[{"id":"sg-est-001","core":true},{"id":"sg-est-011","core":true},{"id":"lec-13-q3c","core":true},{"id":"fd-ser-018","core":true},{"id":"fd-ser-009"},{"id":"sg-est-007"},{"id":"sg-est-010"},{"id":"sg-est-003","challenge":true,"note":"挑戰：調和級數的部分和要到第 83 項才超過 5，部分和長得非常慢。"}]},"geometric-series":{"id":"geometric-series","prerequisites":["partial-sums","sequence-limit"],"next":["telescoping-series"],"related":["power-series"],"objectives":["推出部分和 sₙ = a(1 − rⁿ)/(1 − r)，並由 rⁿ 的極限得到收斂條件 |r| < 1。","用「首項／(1 − 公比)」求和，首項依起始指標認清楚。","判斷 |r| ≥ 1 時發散，不硬套公式。"],"concept":[{"heading":"① 每一項乘同一個數","body":["幾何級數：a + ar + ar² + ar³ + …，每一項都是前一項乘 r（公比）。a 是首項。用 Σ 寫成 Σ_{n=0}^∞ arⁿ。"]},{"heading":"② 部分和有公式","body":["sₙ = a + ar + … + arⁿ⁻¹（前 n 項）。乘上 r：rsₙ = ar + ar² + … + arⁿ。兩式相減，中間全部消掉：sₙ − rsₙ = a − arⁿ。r ≠ 1 時兩邊除以 1 − r：sₙ = a(1 − rⁿ)/(1 − r)。","（r = 1 時每一項都是 a，sₙ = na。）"],"tex":["s_n=\\frac{a\\,(1-r^n)}{1-r}\\qquad(r\\ne 1)"]},{"heading":"③ 收斂的條件","body":["部分和裡唯一跟 n 有關的是 rⁿ。〈數列與數列極限〉說過：|r| < 1 時 rⁿ → 0，所以 sₙ → a/(1 − r)。","|r| ≥ 1（而 a ≠ 0）時發散：r = 1 是 na → ±∞；r = −1 時部分和在 a 與 0 之間跳；|r| > 1 時 rⁿ 爆掉。"],"tex":["\\sum_{n=0}^{\\infty} a r^n=\\frac{a}{1-r}\\qquad(\\lvert r\\rvert<1)"]},{"heading":"④ 實用口訣與陷阱","body":["和 = 首項 /（1 − 公比）。「首項」是級數真正的第一項，不一定是 a：Σ_{n=2}^∞ (1/3)ⁿ 的首項是 (1/3)² = 1/9。","公比也要看清楚：Σ (−1/2)ⁿ 的公比是 −1/2；Σ 5/2ⁿ 的公比是 1/2，5 是乘在外面的常數。","公式只在 |r| < 1 時能用。把 r = 3/2 代進 1/(1 − r) 會得到 −2，一堆正數加起來不可能是負的。"]}],"workedExamples":[{"title":"拆成兩個幾何級數","prompt":"求 Σ_{n=1}^∞ (3ⁿ + 2ⁿ)/6ⁿ。","problemId":"lec-12-q1a","steps":["拆開：(3ⁿ + 2ⁿ)/6ⁿ = (1/2)ⁿ + (1/3)ⁿ。兩個都是 |r| < 1 的幾何級數，各自收斂，可以分開加。","Σ_{n=1}^∞ (1/2)ⁿ：首項 1/2，和 = (1/2)/(1 − 1/2) = 1。","Σ_{n=1}^∞ (1/3)ⁿ：首項 1/3，和 = (1/3)/(1 − 1/3) = 1/2。","總和 = 1 + 1/2 = 3/2。"],"answer":"3/2"},{"title":"循環小數化分數","prompt":"把 0.121212… 化成最簡分數。","problemId":"lec-12-q1b","steps":["0.121212… = 12/100 + 12/100² + 12/100³ + …，首項 12/100，公比 1/100。","和 = (12/100)/(1 − 1/100) = (12/100)/(99/100) = 12/99 = 4/33。"],"answer":"4/33"},{"title":"公比裡有 x","prompt":"對哪些 x，Σ_{n=0}^∞ (x − 1)ⁿ/2ⁿ 收斂？和是多少？","problemId":"lec-12-q1d","steps":["這是公比 r = (x − 1)/2、首項 1 的幾何級數。","收斂 ⇔ |(x − 1)/2| < 1 ⇔ |x − 1| < 2 ⇔ −1 < x < 3。","和 = 1/(1 − (x − 1)/2) = 2/(2 − (x − 1)) = 2/(3 − x)。","這是第一個「和是 x 的函數」的級數，〈冪級數〉會從這裡出發。"],"answer":"−1 < x < 3 時收斂，和為 2/(3 − x)"}],"pitfalls":["起始指標不是 0 時，首項還用 a（例如把 Σ_{n=2}^∞ (1/3)ⁿ 的首項當成 1）。","|r| ≥ 1 時還套 a/(1 − r)。","負的公比少了負號：Σ (−1/2)ⁿ = 1/(1 + 1/2)。","把有限項的公式 a(1 − rⁿ)/(1 − r) 和無窮和 a/(1 − r) 搞混。"],"checks":[{"ask":"Σ_{n=2}^∞ (1/3)ⁿ = ？","options":[{"label":"1/6","correct":true},{"label":"3/2","why":"1/(1 − 1/3) = 3/2 是從 n = 0 開始、首項 1 的和；這裡從 n = 2 開始，首項是 1/9。"},{"label":"1/2","why":"(1/3)/(1 − 1/3) = 1/2 是從 n = 1 開始的和；n = 2 起首項是 1/9，(1/9)/(2/3) = 1/6。"}]},{"ask":"Σ_{n=0}^∞ (3/2)ⁿ 是？","options":[{"label":"發散","correct":true},{"label":"−2","why":"這是把 r = 3/2 硬套 1/(1 − r)。公式只在 |r| < 1 時成立；一堆正數不可能加出負數。"},{"label":"收斂，因為每一項都是有限的數","why":"每一項有限不代表和有限；(3/2)ⁿ → ∞，部分和也 → ∞。"}]},{"ask":"Σ_{n=0}^∞ (−1/2)ⁿ = ？","options":[{"label":"2/3","correct":true},{"label":"2","why":"那是公比 1/2 的答案。公比是 −1/2：1/(1 − (−1/2)) = 2/3。"},{"label":"發散，因為正負交替","why":"|r| = 1/2 < 1 就收斂；正負交替不影響。"}]},{"ask":"首項 a、公比 r（r ≠ 1）的幾何級數，前 n 項的和是？","options":[{"label":"a(1 − rⁿ)/(1 − r)","correct":true},{"label":"a/(1 − r)","why":"這是 |r| < 1 時無窮多項的和（n → ∞ 的極限），不是前 n 項。"},{"label":"arⁿ/(1 − r)","why":"推導是 sₙ − rsₙ = a − arⁿ，分子是 a − arⁿ = a(1 − rⁿ)。"}]}],"practice":[{"id":"fd-ser-001","core":true},{"id":"fd-ser-006","core":true},{"id":"fd-ser-007","core":true},{"id":"fd-ser-017","core":true},{"id":"fd-ser-012","core":true},{"id":"lec-12-q1a","core":true},{"id":"fd-ser-004"},{"id":"tmpl-ser-geo-tail-001"},{"id":"fd-ser-016"},{"id":"lec-12-q1b"},{"id":"fd-ser-011"},{"id":"lec-12-q1d"}]},"telescoping-series":{"id":"telescoping-series","prerequisites":["partial-sums","partial-fractions-linear"],"next":["divergence-test"],"related":["limit-rationalize"],"objectives":["把 aₙ 寫成 bₙ − bₙ₊₁（或 bₙ − bₙ₊ₖ），寫出部分和、看出中間全部相消。","間隔是 k 時，知道前面會留下 k 項、後面會留下 k 項。","相消之後還要取極限：lim bₙ 不存在時級數發散。"],"concept":[{"heading":"① 中間全部消掉","body":["如果每一項都能寫成相鄰兩個數的差 aₙ = bₙ − bₙ₊₁，部分和就會大量相消：sₙ = (b₁ − b₂) + (b₂ − b₃) + … + (bₙ − bₙ₊₁) = b₁ − bₙ₊₁。","所以 Σ aₙ = b₁ − lim bₙ，前提是 lim bₙ 存在；不存在，級數就發散。"],"tex":["s_n=(b_1-b_2)+(b_2-b_3)+\\cdots+(b_n-b_{n+1})=b_1-b_{n+1}"]},{"heading":"② 怎麼拆成差","body":["有理式用〈部分分式 I：相異一次因式〉：1/(n(n + 1)) = 1/n − 1/(n + 1)。","對數用 ln(A/B) = ln A − ln B：ln(n/(n + 1)) = ln n − ln(n + 1)。","根號用有理化（〈0/0：有理化〉）造出差的形式。"]},{"heading":"③ 間隔不是 1 的時候","body":["aₙ = bₙ − bₙ₊₂：正項是 b₁, b₂, b₃, …，負項從 b₃ 開始。前面留下 b₁ + b₂ 沒被消，後面留下 −bₙ₊₁ − bₙ₊₂。一般來說間隔 k 就留頭 k 項、尾 k 項。不確定時，把前四五項和最後兩三項實際寫出來，看誰沒有配對。"]},{"heading":"④ 一定要經過部分和","body":["不要在無窮和裡直接「消項」。先寫出有限的 sₙ，相消是有限和的運算，絕對安全；再取 n → ∞。跳過這一步，就會把 Σ ln(n/(n + 1)) 誤當成收斂（範例 3）。"]}],"workedExamples":[{"title":"最基本的形式","prompt":"求 Σ_{n=1}^∞ 1/(n(n + 1))。","steps":["部分分式：1/(n(n + 1)) = 1/n − 1/(n + 1)。（檢查：通分得 ((n + 1) − n)/(n(n + 1))。）","sₙ = (1 − 1/2) + (1/2 − 1/3) + … + (1/n − 1/(n + 1)) = 1 − 1/(n + 1)。","n → ∞，1/(n + 1) → 0，和 = 1。"],"answer":"1"},{"title":"間隔 2：留兩項","prompt":"求 Σ_{n=2}^∞ 1/(n² − 1)。","problemId":"lec-12-q1c","steps":["n² − 1 = (n − 1)(n + 1)。部分分式：1/(n² − 1) = ½(1/(n − 1) − 1/(n + 1))，間隔 2。","s_N = ½[(1 − 1/3) + (1/2 − 1/4) + (1/3 − 1/5) + … + (1/(N − 1) − 1/(N + 1))]。","正項 1, 1/2, 1/3, …, 1/(N − 1)；負項 1/3, …, 1/(N + 1)。沒被消的：頭 1 + 1/2，尾 −1/N − 1/(N + 1)。","s_N = ½(3/2 − 1/N − 1/(N + 1)) → ½ · 3/2 = 3/4。"],"answer":"3/4"},{"title":"會相消，但發散","prompt":"Σ_{n=1}^∞ ln(n/(n + 1)) 收斂嗎？","problemId":"lec-12-q4d","steps":["ln(n/(n + 1)) = ln n − ln(n + 1)，是望遠鏡形式。","sₙ = (ln 1 − ln 2) + (ln 2 − ln 3) + … + (ln n − ln(n + 1)) = −ln(n + 1)。","n → ∞ 時 −ln(n + 1) → −∞，級數發散。","注意各項 ln(n/(n + 1)) → ln 1 = 0，各項趨近 0 也救不了它。"],"answer":"發散"}],"pitfalls":["部分分式前面的係數（如 ½）漏掉。","間隔 2 時只留下第一項。","相消完忘了檢查 lim bₙ 是否存在。","不寫部分和，直接在無窮和裡消項。"],"checks":[{"ask":"Σ_{n=1}^∞ 1/(n(n + 2)) = ？","options":[{"label":"3/4","correct":true},{"label":"1/2","why":"1/(n(n + 2)) = ½(1/n − 1/(n + 2))，間隔 2，頭會留下 1 和 1/2 兩項；只留 1 就得 1/2。"},{"label":"3/2","why":"1 + 1/2 = 3/2 沒錯，但忘了部分分式前面的 ½。"}]},{"ask":"Σ_{n=1}^∞ ln(n/(n + 1)) 是？","options":[{"label":"發散","correct":true},{"label":"收斂，因為各項 → 0","why":"各項 → 0 不夠。部分和 sₙ = −ln(n + 1) → −∞。"},{"label":"收斂到 −ln 2","why":"只留頭的 ln 1 − ln 2 是錯的：尾巴 −ln(n + 1) 不會消失，它 → −∞。"}]},{"ask":"aₙ = bₙ − bₙ₊₁，而且 lim bₙ = L 存在。Σ_{n=1}^∞ aₙ = ？","options":[{"label":"b₁ − L","correct":true},{"label":"b₁","why":"只有 bₙ → 0 時才對；一般要減掉 bₙ 的極限。"},{"label":"b₁ − b₂","why":"那只是第一項 a₁，不是整個級數的和。"}]},{"ask":"1/(4n² − 1) 的部分分式是？","options":[{"label":"½(1/(2n − 1) − 1/(2n + 1))","correct":true},{"label":"1/(2n − 1) − 1/(2n + 1)","why":"通分得 2/(4n² − 1)，多了 2 倍；要乘 ½。"},{"label":"½(1/(2n − 1) + 1/(2n + 1))","why":"通分得 2n/(4n² − 1)，不對；而且加號不會相消。"}]}],"practice":[{"id":"sg-est-010","core":true},{"id":"depth-ser-003","core":true},{"id":"fd-serx-202","core":true},{"id":"lec-12-q1c","core":true},{"id":"lec-12-q4d","core":true},{"id":"world-006"},{"id":"rel-hard-ser-008"},{"id":"fd-serx-201"},{"id":"fd-serx-306"},{"id":"depth-ser-014"},{"id":"rel-hard-ser-005","challenge":true,"note":"挑戰：1/(n(n + 1)(n + 2)(n + 3)) 寫成 (1/3)[1/(n(n + 1)(n + 2)) − 1/((n + 1)(n + 2)(n + 3))]。"},{"id":"putnam-001","challenge":true,"note":"挑戰：用 arctan 的差角公式，把 arctan(1/(n² + n + 1)) 寫成 arctan(n + 1) − arctan n。"}]},"divergence-test":{"id":"divergence-test","prerequisites":["infinite-series","sequence-limit"],"next":["p-series"],"related":["limit-e-type","alternating-series-test"],"objectives":["證明並使用：Σ aₙ 收斂 ⇒ aₙ → 0；所以 aₙ 不趨近 0 的級數發散。","知道這個判別法只能證明發散，aₙ → 0 時它什麼都不說。","用調和級數 Σ 1/n 說明「各項 → 0 卻發散」。"],"concept":[{"heading":"① 收斂的級數，各項一定 → 0","body":["若 Σ aₙ 收斂到 S，部分和 sₙ → S，sₙ₋₁ 也 → S。而 aₙ = sₙ − sₙ₋₁，所以 aₙ → S − S = 0。這是完整的證明，沒有省略。"]},{"heading":"② 判別法：反過來用","body":["上面那句話的逆否命題：如果 lim aₙ ≠ 0，或 lim aₙ 不存在，那 Σ aₙ 發散。","這叫發散判別（也叫第 n 項判別）。它是拿到任何級數的第一個檢查：算一下各項的極限，不是 0 就結束了。"]},{"heading":"③ 最常見的錯：aₙ → 0 不代表收斂","body":["aₙ → 0 時，判別法沒有結論，級數可能收斂（Σ 1/2ⁿ），也可能發散。標準反例是調和級數 Σ 1/n：各項 → 0，部分和卻沒有上界。","直觀：各項雖然變小，但變小得太慢，把後面的項適當分組，每一組都至少有 ½，可以無限多組（證明在下面）。"]},{"heading":"④ 三種情況一覽","body":["lim aₙ = L ≠ 0：發散。部分和每次大約加 L，不可能停下來。","lim aₙ 不存在（例如在 1 與 −1 附近來回）：發散。","lim aₙ = 0：沒有結論，換別的判別法。後面幾課的〈p 級數〉、比較、比值……全都是為這種情況準備的。","算 lim aₙ 用的是〈數列與數列極限〉的工具：同除最高次、e 型極限、增長速度的比較。常見的陷阱是把 aₙ 的極限和級數的和搞混：各項 → 1/e，跟級數和是多少毫無關係。"]},{"heading":"⑤ 調和級數發散的證明","body":["把各項分組：1/3 + 1/4 > 1/4 + 1/4 = 1/2；1/5 + 1/6 + 1/7 + 1/8 > 4 · 1/8 = 1/2；1/9 到 1/16 共 8 項，每項 ≥ 1/16，和 ≥ 1/2。一般地，第 k 組是 1/(2^{k−1} + 1) 到 1/2^k 共 2^{k−1} 項，每項 ≥ 1/2^k，和 ≥ 1/2。","所以 s_{2^k} ≥ 1 + k/2。k → ∞ 時右邊 → ∞，而部分和遞增，整個 sₙ → ∞，Σ 1/n 發散。"],"collapsible":true}],"workedExamples":[{"title":"極限不是 0","prompt":"Σ_{n=1}^∞ n/(n + 1) 收斂嗎？","problemId":"fd-ser-014","steps":["lim n/(n + 1) = lim 1/(1 + 1/n) = 1 ≠ 0。","由發散判別，級數發散。（部分和大約每次加 1，當然會往上衝。）"],"answer":"發散"},{"title":"要用 e 型極限的","prompt":"Σ_{n=1}^∞ (n/(n + 1))ⁿ 收斂嗎？","problemId":"ser-032","steps":["(n/(n + 1))ⁿ = 1/(1 + 1/n)ⁿ。","(1 + 1/n)ⁿ → e（〈e 型極限〉），所以各項 → 1/e ≈ 0.368 ≠ 0。","由發散判別，級數發散。"],"answer":"發散"},{"title":"極限不存在","prompt":"Σ_{n=1}^∞ (−1)ⁿ n/(n + 1) 收斂嗎？","problemId":"lec-13-m4","steps":["|aₙ| = n/(n + 1) → 1。n 為偶數時 aₙ 靠近 1，n 為奇數時靠近 −1。","aₙ 沒有極限，當然不是「趨近 0」。由發散判別，級數發散。","正負交替不能救它：後面會學的〈交錯級數判別〉要求各項的大小 → 0。"],"answer":"發散"}],"pitfalls":["看到 aₙ → 0 就說收斂。","aₙ → 0 時說「由發散判別，級數收斂」：這個判別法從來不能證明收斂。","把 lim aₙ 和級數和搞混：各項 → 1/e，不是級數和是 1/e。","以為正負交替就一定收斂。"],"checks":[{"ask":"已知 aₙ → 0。關於 Σ aₙ 可以說什麼？","options":[{"label":"光憑這點無法判斷","correct":true},{"label":"一定收斂","why":"調和級數 Σ 1/n 各項 → 0，卻發散。"},{"label":"一定發散","why":"Σ 1/2ⁿ 各項 → 0，而且收斂到 1。"}]},{"ask":"Σ (2n² + 1)/(n² + 5) 是？","options":[{"label":"發散，因為各項 → 2","correct":true},{"label":"收斂，因為分子分母同次","why":"同次只說明各項趨近一個非零常數 2；各項不 → 0，部分和每次約加 2，會往上衝。"},{"label":"發散判別無法判斷","why":"判別法只有在 aₙ → 0 時沒結論；這裡極限是 2 ≠ 0，結論就是發散。"}]},{"ask":"Σ cos(1/n) 是？","options":[{"label":"發散，因為各項 → 1","correct":true},{"label":"收斂，因為 1/n → 0","why":"各項是 cos(1/n)，不是 1/n；cos(1/n) → cos 0 = 1。"},{"label":"無法判斷","why":"各項的極限是 1 ≠ 0，發散判別直接給出發散。"}]},{"ask":"「Σ aₙ 收斂 ⇒ aₙ → 0」的證明關鍵是？","options":[{"label":"aₙ = sₙ − sₙ₋₁，兩個部分和都 → S","correct":true},{"label":"收斂的級數各項越來越小","why":"這只是重述結論，沒有用到「收斂」的定義（部分和有極限）。"},{"label":"Σ 1/n 發散","why":"調和級數是反方向的反例（aₙ → 0 但發散），證不了這個方向。"}]}],"practice":[{"id":"fd-ser-014","core":true},{"id":"fd-serx-206","core":true},{"id":"mob-conv-010","core":true},{"id":"ser-032","core":true},{"id":"lec-12-m2","core":true},{"id":"lec-13-m4"},{"id":"cx-ser-005"},{"id":"rel-hard-ser-010"},{"id":"lec-12-q4a","challenge":true,"note":"挑戰：用歸納法寫出 H_{2^k} ≥ 1 + k/2，就是本課分組證明的嚴格版。"}]},"p-series":{"id":"p-series","prerequisites":["divergence-test","improper-p-test"],"next":["integral-test"],"related":["improper-infinite","basel-problem","comparison-test"],"objectives":["記住並使用：Σ 1/nᵖ 收斂 ⇔ p > 1。","先合併指數，把式子化成 1/nᵖ 再讀出 p。","用「長條與曲線」的圖說明為什麼它跟 ∫₁^∞ dx/xᵖ 同生共死。"],"concept":[{"heading":"① 結論","body":["p 級數 Σ_{n=1}^∞ 1/nᵖ：p > 1 時收斂，p ≤ 1 時發散。p = 1 就是調和級數，剛好站在發散那一側。"],"tex":["\\sum_{n=1}^{\\infty}\\frac{1}{n^p}\\ \\text{收斂}\\iff p>1"]},{"heading":"② 為什麼：跟瑕積分比（直觀，不是證明）","body":["把第 n 項畫成 [n, n + 1] 上高 1/nᵖ 的長條。長條的左上角貼著曲線 y = 1/xᵖ，曲線往右遞減，所以長條都蓋住曲線下的面積：Σ 1/nᵖ ≥ ∫₁^∞ dx/xᵖ。把長條往左移一格，就全部躲到曲線底下：Σ_{n≥2} 1/nᵖ ≤ ∫₁^∞ dx/xᵖ。","級數被積分從上下夾住，兩者一起有限、一起無限。〈p 判別〉說 ∫₁^∞ dx/xᵖ 收斂 ⇔ p > 1，級數也就一樣。下一課〈積分判別〉把這張圖變成正式的定理。"]},{"heading":"③ 三段式","body":["p ≤ 0：各項 1/nᵖ = n^{|p|} 不趨近 0，〈發散判別〉直接說發散。","0 < p ≤ 1：各項 → 0，但部分和仍然沒有上界，發散。","p > 1：收斂。分界很銳利：p = 1.001 也收斂，只是收斂得極慢。"]},{"heading":"④ 收斂不等於知道和","body":["判別法只說收不收斂。和本身通常很難求：Σ 1/n² = π²/6（〈Basel 問題〉），Σ 1/n³ ≈ 1.202 至今沒有簡單的封閉形式。p 級數最大的用處是當「標準尺」：後面的〈比較判別〉要拿它跟別的級數比。"]}],"workedExamples":[{"title":"p = 1/2","prompt":"Σ_{n=1}^∞ 1/√n 收斂嗎？","problemId":"ser-031","steps":["1/√n = 1/n^{1/2}，p = 1/2 ≤ 1。","發散。對照積分：∫₁^N x^{−1/2} dx = 2√N − 2 → ∞（例如 N = 10⁶ 時是 1998）。"],"answer":"發散"},{"title":"先合併指數","prompt":"Σ_{n=1}^∞ √n / n² 收斂嗎？","steps":["√n/n² = n^{1/2}/n² = 1/n^{2 − 1/2} = 1/n^{3/2}。","p = 3/2 > 1，收斂。（和約為 2.612，判別法本身不提供這個值。）"],"answer":"收斂"},{"title":"收斂加發散","prompt":"Σ_{n=1}^∞ (2/n³ + 5/∛n) 收斂嗎？","steps":["拆成兩個 p 級數：Σ 2/n³（p = 3，收斂）與 Σ 5/n^{1/3}（p = 1/3，發散）。","收斂加發散一定發散：如果總和收斂，減掉收斂的 Σ 2/n³ 之後，Σ 5/n^{1/3} 也得收斂，矛盾。","所以整個級數發散。注意「發散加發散」就沒有這種保證：Σ 1/n 與 Σ (−1/n) 各自發散，相加卻是 0。"],"answer":"發散"},{"title":"用圖把和夾住","prompt":"不求 Σ 1/n² 的確切值，用積分估計它的範圍。","steps":["長條蓋住曲線：Σ_{n=1}^∞ 1/n² ≥ ∫₁^∞ dx/x² = 1。","第一項 1 單獨拿出來，其餘長條往左移一格躲到曲線下：Σ_{n=1}^∞ 1/n² ≤ 1 + ∫₁^∞ dx/x² = 2。","所以 1 ≤ Σ 1/n² ≤ 2。真正的值 π²/6 ≈ 1.645 確實在這之間。"],"answer":"1 ≤ Σ 1/n² ≤ 2"}],"pitfalls":["把條件記成 p > 0 或 p ≥ 1。","以為各項 → 0（p > 0）就收斂。","沒合併指數就讀 p：√n/n² 的 p 是 3/2，不是 2 或 1/2。","以為判別法也給出級數的和。","看到兩個級數相加，以為各自發散的話相加也一定發散。"],"checks":[{"ask":"Σ 1/n^{0.9} 是？","options":[{"label":"發散","correct":true},{"label":"收斂，因為各項 → 0","why":"各項 → 0 不夠；p = 0.9 ≤ 1，部分和沒有上界。"},{"label":"收斂，因為 p > 0","why":"收斂條件是 p > 1；p > 0 只保證各項 → 0。"}]},{"ask":"Σ 1/n^{1.001} 是？","options":[{"label":"收斂","correct":true},{"label":"發散，因為它跟調和級數幾乎一樣","why":"分界很銳利：只要 p > 1 就收斂，只是收斂得很慢。"},{"label":"無法判斷","why":"p 級數的結論非常明確：p = 1.001 > 1，收斂。"}]},{"ask":"Σ √n / n² 的 p 是多少？","options":[{"label":"3/2，所以收斂","correct":true},{"label":"1/2，所以發散","why":"√n 在分子，要從分母的指數扣掉：2 − 1/2 = 3/2。"},{"label":"2，所以收斂","why":"結論碰巧對，但忽略了分子的 √n；指數是 3/2。"}]},{"ask":"Σ_{n=1}^∞ n（也就是 p = −1）是？","options":[{"label":"發散，因為各項不趨近 0","correct":true},{"label":"收斂，因為 p < 1","why":"條件反了：p > 1 才收斂。"},{"label":"要用積分判別才知道","why":"不必：p ≤ 0 時各項不 → 0，發散判別一步就結束。"}]}],"practice":[{"id":"cx-ser-005","core":true},{"id":"cx-ser-002","core":true},{"id":"ser-031","core":true},{"id":"fd-ser-013","core":true},{"id":"fd-serx-205","core":true},{"id":"lec-12-m5"}]},"integral-test":{"id":"integral-test","prerequisites":["p-series","improper-infinite"],"next":["comparison-test"],"related":["partial-sums","u-sub-definite","monotone-convergence-sequence"],"objectives":["完整說出積分判別的條件：f 在 [N, ∞) 上連續、為正、遞減，且 aₙ = f(n)。","檢查遞減（常用 f′ ≤ 0），算瑕積分，判斷級數收斂或發散。","用 ∫_{N+1}^∞ f ≤ R_N ≤ ∫_N^∞ f 估計部分和的誤差。"],"concept":[{"heading":"① 定理","body":["設 f 在 [N, ∞) 上連續、為正、遞減，而且 aₙ = f(n)（n ≥ N）。那麼 Σ_{n=N}^∞ aₙ 與 ∫_N^∞ f(x) dx 同時收斂或同時發散。","三個條件（連續、正、遞減）都要檢查。遞減只要從某個 N 開始成立就行，前面有限項不影響收斂。"]},{"heading":"② 圖像","body":["跟〈p 級數〉那張圖一樣：f 遞減，所以在 [k, k + 1] 上 f(k + 1) ≤ f(x) ≤ f(k)。高 f(k) 的長條蓋住曲線，高 f(k + 1) 的長條躲在曲線下。級數被積分從上下夾住，有限就一起有限，無限就一起無限。","注意：收斂時，級數的和一般不等於積分的值。判別法只說「同生共死」。"]},{"heading":"③ 條件為什麼不能少","body":["遞減是夾住的關鍵。反例：f(x) = sin²(πx) 連續、非負，但不遞減。aₙ = sin²(πn) = 0，級數收斂到 0；∫₁^∞ sin²(πx) dx 卻是無限大（每一段 [k, k + 1] 貢獻 1/2）。沒有遞減，級數與積分可以各走各的路。"]},{"heading":"④ 誤差估計","body":["同一張圖還能估尾巴。用 s_N 近似和 S 時，尾巴 R_N = Σ_{n=N+1}^∞ aₙ 滿足："],"tex":["\\int_{N+1}^{\\infty} f(x)\\,dx\\ \\le\\ R_N\\ \\le\\ \\int_{N}^{\\infty} f(x)\\,dx"]},{"heading":"⑤ 證明","body":["f 遞減，在 [k, k + 1] 上 f(k + 1) ≤ f(x) ≤ f(k)，積分得 a_{k+1} ≤ ∫_k^{k+1} f ≤ aₖ。從 k = N 加到 M − 1：Σ_{k=N+1}^{M} aₖ ≤ ∫_N^M f ≤ Σ_{k=N}^{M−1} aₖ。","f > 0，部分和與 ∫_N^M f 都隨 M 遞增。若積分收斂，左式說部分和有上界，由〈單調收斂定理〉級數收斂；若積分發散（→ ∞），右式說部分和也 → ∞。誤差估計是同一組不等式取 M → ∞ 的結果。"],"collapsible":true}],"workedExamples":[{"title":"發散：ln ln","prompt":"Σ_{n=2}^∞ 1/(n ln n) 收斂嗎？","problemId":"lec-12-q2b","steps":["f(x) = 1/(x ln x) 在 [2, ∞)：連續；x ln x > 0，所以 f > 0；x 與 ln x 都遞增，分母遞增，f 遞減。條件成立。","令 u = ln x（〈定積分換元〉）：∫₂^M dx/(x ln x) = ln(ln M) − ln(ln 2)。","M → ∞ 時 ln(ln M) → ∞（很慢：M = 10⁶ 時才約 2.99），積分發散，所以級數發散。"],"answer":"發散"},{"title":"收斂：要先證遞減","prompt":"Σ_{n=1}^∞ n e^{−n²} 收斂嗎？","problemId":"lec-12-q2c","steps":["f(x) = x e^{−x²}：連續、在 x ≥ 1 為正。遞減：f′(x) = e^{−x²}(1 − 2x²)，x ≥ 1 時 1 − 2x² < 0，所以 f′ < 0。","∫₁^∞ x e^{−x²} dx：令 u = x²，= ½∫₁^∞ e^{−u} du = 1/(2e)。有限。","積分收斂，級數收斂。（級數的和不是 1/(2e)。）"],"answer":"收斂"},{"title":"要取幾項？","prompt":"用 sₙ = Σ_{k=1}^{n} 1/k³ 近似 Σ 1/k³，要保證誤差 Rₙ ≤ 0.005，n 至少多少？","problemId":"lec-12-q2d","steps":["f(x) = 1/x³ 在 [1, ∞) 連續、為正、遞減。","Rₙ ≤ ∫ₙ^∞ x⁻³ dx = 1/(2n²)。","要 1/(2n²) ≤ 0.005，即 n² ≥ 100，n ≥ 10。","檢查：n = 10 時上界是 0.005，實際的尾巴約 0.0045。"],"answer":"n = 10"}],"pitfalls":["沒檢查遞減就用（或只檢查了正與連續）。","以為級數的和等於積分的值。","誤差估計的上下限差一：上界是 ∫_N^∞，下界是 ∫_{N+1}^∞。","把積分判別用在正負交替的級數上。"],"checks":[{"ask":"用積分判別之前，f 在 [N, ∞) 上要滿足哪些條件？","options":[{"label":"連續、為正、遞減","correct":true},{"label":"可微、為正","why":"不需要可微；少了最關鍵的遞減。f′ 只是檢查遞減的工具之一。"},{"label":"連續，而且 f(n) → 0","why":"f(n) → 0 不夠：sin²(πx) 的例子顯示，不遞減時級數與積分可以結論不同。"}]},{"ask":"Σ_{n=2}^∞ 1/(n (ln n)²) 是？","options":[{"label":"收斂","correct":true},{"label":"發散，因為它跟 Σ 1/(n ln n) 很像","why":"多一次方的 ln 就不一樣：∫₂^∞ dx/(x (ln x)²) = [−1/ln x]₂^∞ = 1/ln 2，有限。"},{"label":"收斂，而且和等於 1/ln 2","why":"積分判別只說同收同散；級數的和一般不等於積分的值。"}]},{"ask":"f 符合積分判別的條件，且 ∫₁^∞ f(x) dx = 3。關於 Σ_{n=1}^∞ f(n)？","options":[{"label":"收斂，但和不一定是 3","correct":true},{"label":"收斂，而且和是 3","why":"長條的面積和曲線下的面積不一樣；長條在曲線上方，和其實比 3 大。"},{"label":"發散","why":"積分收斂，級數就收斂；它們同生共死。"}]},{"ask":"用前 100 項近似 Σ 1/n²，誤差 R₁₀₀ 的上界（積分估計）是？","options":[{"label":"∫₁₀₀^∞ dx/x² = 1/100","correct":true},{"label":"1/101²","why":"那只是下一項；尾巴有無窮多項，加起來大得多。"},{"label":"1/100²","why":"a₁₀₀ 已經算進部分和裡了，它不是誤差。"}]}],"practice":[{"id":"ser-024","core":true},{"id":"ser-037","core":true},{"id":"lec-12-q2c","core":true},{"id":"sg-est-004","core":true},{"id":"lec-12-q2d","core":true},{"id":"cx-smid-013"},{"id":"cx-smid-012"},{"id":"lec-12-q2a"},{"id":"lec-12-q4b"},{"id":"sg-est-005"},{"id":"an-sr-003","challenge":true,"note":"挑戰：Σ 1/(n (ln n)²) 收斂得極慢，用積分上界 1/ln N 保證尾巴小於 0.1，N 要兩萬多。"}]},"comparison-test":{"id":"comparison-test","prerequisites":["p-series","geometric-series"],"next":["limit-comparison-test"],"related":["monotone-convergence-sequence","improper-comparison"],"objectives":["說出比較判別：0 ≤ aₙ ≤ bₙ 時，Σ bₙ 收斂 ⇒ Σ aₙ 收斂；Σ aₙ 發散 ⇒ Σ bₙ 發散。","抓住主要項，選 p 級數或幾何級數當比較對象。","分辨「方向對、有結論」與「方向錯、沒結論」的不等式。"],"concept":[{"heading":"① 直觀：被收斂的壓住","body":["各項都 ≥ 0 的級數，部分和只會往上走。如果每一項都比一個收斂級數的對應項小，部分和就被那個級數的和壓住，有上界，所以收斂（〈單調收斂定理〉）。反過來，每一項都比一個發散級數的對應項大，部分和就被拖著衝向 ∞。"]},{"heading":"② 定理","body":["設從某一項開始 0 ≤ aₙ ≤ bₙ。","若 Σ bₙ 收斂，則 Σ aₙ 收斂（大的收斂，小的也收斂）。","若 Σ aₙ 發散，則 Σ bₙ 發散（小的發散，大的也發散）。","其餘兩種組合沒有結論：比發散的小、比收斂的大，都什麼都說明不了。"]},{"heading":"③ 怎麼找比較對象","body":["先猜：只留下 n 很大時的主要項。1/(2ⁿ + n) 的分母裡 2ⁿ 遠大於 n，所以它「長得像」1/2ⁿ。猜它收斂，就要找一個比它大、而且收斂的級數；猜它發散，就要找一個比它小、而且發散的。","標準尺：p 級數（〈p 級數〉）與幾何級數。常用的不等式：ln n < n、|sin n| ≤ 1、去掉分母裡的正項會變大。","不等式方向剛好不對時（例如 1/(n² − 3) 比 1/n² 大），可以改比 2/n²，或直接用下一課的〈極限比較判別〉。"]},{"heading":"④ 證明","body":["aₙ ≥ 0，部分和 sₙ = Σ_{k≤n} aₖ 遞增。若 Σ bₖ = B 收斂，則 sₙ ≤ Σ_{k≤n} bₖ ≤ B（bₖ ≥ 0），有上界，由單調收斂定理收斂。第二句是第一句的逆否命題。「從某一項開始」只是丟掉前面有限項，不影響收斂。"],"collapsible":true}],"workedExamples":[{"title":"跟幾何級數比","prompt":"Σ_{n=1}^∞ 1/(2ⁿ + n) 收斂嗎？","problemId":"lec-12-q3a","steps":["主要項是 2ⁿ，猜它像 Σ 1/2ⁿ，收斂。","要找比它大的收斂級數：分母去掉正的 n 會變小，分式變大，1/(2ⁿ + n) < 1/2ⁿ。","Σ 1/2ⁿ 是公比 1/2 的幾何級數，收斂。由比較判別，原級數收斂。"],"answer":"收斂"},{"title":"用 ln n < n 壓掉對數","prompt":"Σ_{n=1}^∞ (ln n)/n³ 收斂嗎？","problemId":"lec-12-q3d","steps":["ln n 長得比 n 慢，猜它比 1/n² 還小，收斂。","n ≥ 1 時 0 ≤ ln n < n，所以 0 ≤ (ln n)/n³ < n/n³ = 1/n²。","Σ 1/n² 是 p = 2 的 p 級數，收斂。由比較判別，原級數收斂。"],"answer":"收斂"},{"title":"從下面比，證明發散","prompt":"Σ_{n=3}^∞ (ln n)/n 收斂嗎？","steps":["ln n 會長大，猜它比 1/n 還大，發散。","n ≥ 3 時 ln n ≥ ln 3 > 1，所以 (ln n)/n > 1/n。","Σ 1/n 發散，比它大的也發散。"],"answer":"發散"}],"pitfalls":["aₙ ≤ bₙ 而 Σ bₙ 發散，就說 Σ aₙ 發散。","aₙ ≥ bₙ 而 Σ bₙ 收斂，就說 Σ aₙ 收斂。","用在有負項的級數上：比較判別要求 aₙ ≥ 0。","不等式只對大的 n 成立時，沒有說明「從第幾項開始」。"],"checks":[{"ask":"0 ≤ aₙ ≤ bₙ，且 Σ bₙ 發散。關於 Σ aₙ？","options":[{"label":"無法判斷","correct":true},{"label":"發散","why":"比發散的小，可能收斂：1/n² ≤ 1/n，Σ 1/n² 卻收斂。"},{"label":"收斂","why":"也可能發散：1/(2n) ≤ 1/n，Σ 1/(2n) 發散。"}]},{"ask":"判斷 Σ 1/(n² + 5)，正確的比較是？","options":[{"label":"1/(n² + 5) < 1/n²，Σ 1/n² 收斂，所以收斂","correct":true},{"label":"1/(n² + 5) < 1/n，Σ 1/n 發散，所以發散","why":"比發散的小得不到任何結論，方向沒用。"},{"label":"1/(n² + 5) > 1/n³，Σ 1/n³ 收斂，所以收斂","why":"比收斂的大得不到結論；而且 n 大時這個不等式其實是對的，卻沒有用。"}]},{"ask":"Σ_{n=2}^∞ 1/(n² − 3)：發現 1/(n² − 3) > 1/n²。下一步？","options":[{"label":"改比 2/n²：n ≥ 3 時 n² − 3 ≥ n²/2，所以 1/(n² − 3) ≤ 2/n²","correct":true},{"label":"結論是發散","why":"比收斂的級數大，得不到發散；它其實收斂。"},{"label":"結論是收斂，因為它和 1/n² 很像","why":"「很像」不是比較判別；要嘛找到方向對的不等式，要嘛用極限比較判別。"}]},{"ask":"Σ (2 + sin n)/n 是？","options":[{"label":"發散，因為 (2 + sin n)/n ≥ 1/n","correct":true},{"label":"收斂，因為 sin n 有界","why":"有界的是分子；分子在 1 到 3 之間，整項跟 1/n 一樣大小，而 Σ 1/n 發散。"},{"label":"無法比較，因為 sin n 會振盪","why":"2 + sin n 永遠 ≥ 1，振盪也跑不出這個範圍，可以拿 1/n 從下面比。"}]}],"practice":[{"id":"lec-12-q3a","core":true},{"id":"ser-036","core":true},{"id":"lec-12-q3d","core":true},{"id":"lec-12-m4","core":true},{"id":"lec-13-q1c"},{"id":"lec-12-q3b"}]},"limit-comparison-test":{"id":"limit-comparison-test","prerequisites":["comparison-test"],"next":["ratio-test"],"related":["limit-trig-standard","limit-at-infinity"],"objectives":["說出極限比較判別：aₙ, bₙ > 0 且 lim aₙ/bₙ = c，0 < c < ∞，則兩級數同收同散。","用主要項選出 bₙ（通常是 1/nᵖ），算比值的極限。","知道 c = 0 或 c = ∞ 時只剩單方向的結論。"],"concept":[{"heading":"① 為什麼需要它","body":["〈比較判別〉要一個方向剛好對的不等式。(n + 1)/(n³ − n + 5) 明明「長得像」1/n²，但要寫出 ≤ C/n² 得處理分母裡的 −n，很煩。其實我們只關心兩者在 n 很大時的比例，所以改看比值的極限。"]},{"heading":"② 定理","body":["設從某一項開始 aₙ > 0、bₙ > 0，且 lim aₙ/bₙ = c，0 < c < ∞（一個正的有限數）。則 Σ aₙ 與 Σ bₙ 同時收斂或同時發散。","直觀：比值靠近 c，代表 n 很大時 aₙ ≈ c · bₙ，兩個級數只差一個倍數，命運相同。"]},{"heading":"③ 怎麼選 bₙ","body":["有理式（含根號）：分子分母各留最高次項。(3n² + 1)/(n³ + 2) 的主要部分是 3n²/n³ = 3/n，取 bₙ = 1/n（常數 3 不用帶）。","小量代換：n → ∞ 時 1/n → 0，sin(1/n) 和 1/n 的比值 → 1（〈三角標準極限〉）；1 − cos(1/n) 和 1/(2n²) 的比值 → 1。","選好之後一定要真的算比值的極限，確認它是正的有限數。"]},{"heading":"④ c = 0 或 c = ∞","body":["c = 0：aₙ 比 bₙ 小很多。Σ bₙ 收斂 ⇒ Σ aₙ 收斂；Σ bₙ 發散時沒有結論。","c = ∞：aₙ 比 bₙ 大很多。Σ bₙ 發散 ⇒ Σ aₙ 發散；Σ bₙ 收斂時沒有結論。","得到 0 或 ∞ 通常表示 bₙ 選錯了次方，回去重選比較省事。"]},{"heading":"⑤ 證明","body":["取 ε = c/2。因為 aₙ/bₙ → c，存在 N 使 n ≥ N 時 |aₙ/bₙ − c| < c/2，也就是 (c/2) bₙ < aₙ < (3c/2) bₙ。右半邊：Σ bₙ 收斂 ⇒ Σ (3c/2)bₙ 收斂 ⇒（比較判別）Σ aₙ 收斂。左半邊：Σ bₙ 發散 ⇒ Σ (c/2)bₙ 發散 ⇒ Σ aₙ 發散。c > 0 保證了 c/2 > 0，左半邊才用得上。"],"collapsible":true}],"workedExamples":[{"title":"像 1/n：發散","prompt":"Σ_{n=1}^∞ (3n² + 1)/(n³ + 2) 收斂嗎？","problemId":"gap-ser-lc-001","steps":["主要項 3n²/n³ = 3/n，取 bₙ = 1/n。兩者都為正。","aₙ/bₙ = (3n³ + n)/(n³ + 2) → 3，是正的有限數。","Σ 1/n 發散，所以原級數發散。"],"answer":"發散"},{"title":"像 1/n²：收斂","prompt":"Σ_{n=1}^∞ (n + 1)/(n³ − n + 5) 收斂嗎？","problemId":"lec-12-q3b","steps":["n ≥ 1 時分母 n³ − n + 5 = n(n² − 1) + 5 > 0，各項為正。","主要項 n/n³ = 1/n²，取 bₙ = 1/n²。","aₙ/bₙ = (n³ + n²)/(n³ − n + 5) → 1。","Σ 1/n² 收斂（p = 2），所以原級數收斂。"],"answer":"收斂"},{"title":"小量代換","prompt":"Σ_{n=1}^∞ sin(1/n) 收斂嗎？","problemId":"lec-12-q3c","steps":["0 < 1/n ≤ 1 < π，所以 sin(1/n) > 0，可以用。","取 bₙ = 1/n。令 t = 1/n → 0⁺：sin(1/n)/(1/n) = (sin t)/t → 1。","Σ 1/n 發散，所以 Σ sin(1/n) 發散。","注意：各項 sin(1/n) → 0，發散判別在這裡沒有結論。"],"answer":"發散"}],"pitfalls":["比值算出 0 或 ∞，卻照樣說兩者同收同散。","bₙ 只看分子或只看分母的最高次。","用在有負項的級數上：要求 aₙ, bₙ > 0。","選了 bₙ 卻沒有真的算比值的極限。"],"checks":[{"ask":"判斷 Σ (2n + 3)/(n³ + 1)，最好的 bₙ 是？","options":[{"label":"1/n²","correct":true},{"label":"1/n","why":"主要項是 2n/n³ = 2/n²；跟 1/n 比，比值 → 0，配上發散的 Σ 1/n 沒有結論。"},{"label":"1/n³","why":"漏了分子的 n；比值 → ∞，配上收斂的 Σ 1/n³ 也沒有結論。"}]},{"ask":"lim aₙ/bₙ = 0，而且 Σ bₙ 發散。關於 Σ aₙ？","options":[{"label":"無法判斷","correct":true},{"label":"發散","why":"aₙ 比 bₙ 小很多，可能收斂：aₙ = 1/n²、bₙ = 1/n。"},{"label":"收斂","why":"也可能發散：aₙ = 1/(n ln n)、bₙ = 1/n，比值 1/ln n → 0，但 Σ 1/(n ln n) 發散。"}]},{"ask":"Σ (1 − cos(1/n)) 是？","options":[{"label":"收斂：跟 1/n² 比，比值 → 1/2","correct":true},{"label":"發散：跟 1/n 比","why":"1 − cos(1/n) 比 1/n 小得多，比值 → 0，配上發散的 Σ 1/n 沒有結論。"},{"label":"發散：由發散判別","why":"各項 → 1 − cos 0 = 0，發散判別沒有結論。"}]},{"ask":"極限比較判別需要的是？","options":[{"label":"aₙ, bₙ > 0，且 aₙ/bₙ 趨近一個正的有限數","correct":true},{"label":"aₙ ≤ bₙ","why":"那是比較判別的條件；極限比較只看比值的極限，不需要大小關係。"},{"label":"lim aₙ = lim bₙ","why":"兩者通常都 → 0，相等沒有意義；重要的是它們的比值。"}]}],"practice":[{"id":"gap-ser-lc-001","core":true},{"id":"rel-adv-018","core":true},{"id":"gap-ser-lc-002","core":true},{"id":"lec-12-q3b","core":true},{"id":"lec-12-q3c","core":true},{"id":"lec-12-m4"}]},"ratio-test":{"id":"ratio-test","prerequisites":["geometric-series","comparison-test","limit-e-type"],"next":["root-test"],"related":["absolute-convergence","limit-comparison-test","radius-of-convergence"],"objectives":["算 L = lim |aₙ₊₁/aₙ|，並說出 L < 1、L > 1、L = 1 各自的結論。","熟練約分 (n + 1)!/n!、(n/(n + 1))ⁿ 這類比值。","看出什麼時候該用比值判別（階乘、bⁿ、nⁿ），什麼時候它一定失效（有理式、p 級數）。"],"concept":[{"heading":"① 直觀：最後長得像幾何級數","body":["如果相鄰兩項的比 aₙ₊₁/aₙ 趨近 L，那麼 n 很大時每一項大約是前一項的 L 倍，級數的尾巴長得像公比 L 的幾何級數（〈幾何級數〉）。L < 1 就收斂，L > 1 就發散。"]},{"heading":"② 定理","body":["設 L = lim_{n→∞} |aₙ₊₁/aₙ|（可以是 ∞）。","L < 1：Σ aₙ 收斂，而且是絕對收斂（Σ |aₙ| 也收斂，見〈絕對收斂〉；正項級數就是收斂）。","L > 1 或 L = ∞：發散。此時從某一項起 |aₙ₊₁| > |aₙ|，各項不趨近 0。","L = 1：沒有結論。Σ 1/n 和 Σ 1/n² 的比值極限都是 1，一個發散、一個收斂。"]},{"heading":"③ 什麼時候用","body":["有階乘、bⁿ、nⁿ 的級數：比值會大量約分。(n + 1)! / n! = n + 1；2ⁿ⁺¹/2ⁿ = 2；(n + 1)ⁿ⁺¹/nⁿ 要拆成 (n + 1) · ((n + 1)/n)ⁿ，後者 → e（〈e 型極限〉）。","有理式、根號、p 級數：比值一定 → 1，比值判別必定失效。這類用〈極限比較判別〉。"]},{"heading":"④ 證明","body":["L < 1：取 r 滿足 L < r < 1。存在 N 使 n ≥ N 時 |aₙ₊₁| ≤ r|aₙ|，反覆用得 |a_{N+k}| ≤ rᵏ |a_N|。Σ rᵏ|a_N| 是公比 r < 1 的幾何級數，由比較判別 Σ |aₙ| 收斂；絕對收斂推出收斂。L > 1：從某項起 |aₙ₊₁| > |aₙ| > 0，|aₙ| 遞增而且不是 0，不可能 → 0，由發散判別發散。"],"collapsible":true}],"workedExamples":[{"title":"多項式 × 指數","prompt":"Σ_{n=1}^∞ n²/2ⁿ 收斂嗎？","problemId":"lec-13-q2a","steps":["aₙ₊₁/aₙ = ((n + 1)²/2ⁿ⁺¹) · (2ⁿ/n²) = ((n + 1)/n)² · (1/2)。","(n + 1)/n → 1，所以 L = 1/2 < 1。","收斂。"],"answer":"收斂"},{"title":"階乘配 nⁿ","prompt":"Σ_{n=1}^∞ n!/nⁿ 收斂嗎？","problemId":"lec-13-m2","steps":["aₙ₊₁/aₙ = ((n + 1)!/(n + 1)ⁿ⁺¹) · (nⁿ/n!) = (n + 1) · nⁿ/(n + 1)ⁿ⁺¹ = nⁿ/(n + 1)ⁿ = (n/(n + 1))ⁿ。","(n/(n + 1))ⁿ = 1/(1 + 1/n)ⁿ → 1/e ≈ 0.368 < 1。","收斂。"],"answer":"收斂（L = 1/e）"},{"title":"L > 1","prompt":"Σ_{n=1}^∞ nⁿ/n! 收斂嗎？","problemId":"lec-13-q2d","steps":["aₙ₊₁/aₙ = ((n + 1)ⁿ⁺¹/(n + 1)!) · (n!/nⁿ) = (n + 1)ⁿ/nⁿ = (1 + 1/n)ⁿ。","→ e ≈ 2.718 > 1。","發散。（其實 nⁿ/n! ≥ 1，各項根本不趨近 0。）"],"answer":"發散（L = e）"}],"pitfalls":["L = 1 時說收斂或發散。","對有理式用比值判別，算出 1 之後卡住。","(n + 1)! 與 n! 約分錯，或 (n + 1)ⁿ⁺¹ 少拆一個 (n + 1)。","比值寫反成 aₙ/aₙ₊₁，結論跟著顛倒。"],"checks":[{"ask":"比值判別得到 L = 1，代表？","options":[{"label":"這個判別法沒有結論","correct":true},{"label":"收斂","why":"Σ 1/n 的 L 也是 1，它發散。"},{"label":"發散","why":"Σ 1/n² 的 L 也是 1，它收斂。"}]},{"ask":"Σ 3ⁿ/n! 用比值判別：","options":[{"label":"比值 3/(n + 1) → 0，收斂","correct":true},{"label":"比值 → 3，發散","why":"只看了 3ⁿ⁺¹/3ⁿ = 3，忘了階乘也要約：n!/(n + 1)! = 1/(n + 1)。"},{"label":"比值 → 1，無法判斷","why":"3/(n + 1) → 0，不是 1；階乘長得比 3ⁿ 快。"}]},{"ask":"Σ (n² + 1)/(n⁴ + 3) 該用什麼？","options":[{"label":"極限比較（跟 1/n² 比）；比值判別會得到 L = 1","correct":true},{"label":"比值判別，L < 1 所以收斂","why":"有理式的相鄰比值一定 → 1，比值判別在這裡沒有結論。"},{"label":"比值判別，L > 1 所以發散","why":"比值 → 1，不是大於 1；而且這個級數其實收斂。"}]},{"ask":"Σ (2n)!/(n!)² 的比值極限是？","options":[{"label":"4，所以發散","correct":true},{"label":"2，所以發散","why":"(2n + 2)!/(2n)! 有兩個因子 (2n + 2)(2n + 1)，不是一個；除以 (n + 1)² 之後 → 4。"},{"label":"1，無法判斷","why":"分子分母都是 n 的二次式，但領導係數 4 和 1 不同，極限是 4。"}]}],"practice":[{"id":"lec-13-q2a","core":true},{"id":"lec-13-q2b","core":true},{"id":"mob-conv-006","core":true},{"id":"lec-13-m2","core":true},{"id":"lec-13-m3","core":true},{"id":"fd-serx-305"},{"id":"cx-smid-011"},{"id":"lec-13-q2d"}]},"root-test":{"id":"root-test","prerequisites":["ratio-test"],"next":["alternating-series-test"],"related":["sequence-limit","limit-e-type"],"objectives":["算 L = lim |aₙ|^{1/n}，結論與比值判別相同：L < 1 絕對收斂，L > 1 發散，L = 1 沒有結論。","看到「整個式子的 n 次方」就想到根值判別。","會用 n^{1/n} → 1、C^{1/n} → 1，把多項式因子開掉。"],"concept":[{"heading":"① 直觀：每一項大約是 Lⁿ","body":["如果 |aₙ|^{1/n} → L，那麼 n 很大時 |aₙ| ≈ Lⁿ，級數長得像公比 L 的幾何級數。跟〈比值判別〉同一個想法，只是改用「開 n 次方」去讀出公比。"]},{"heading":"② 定理","body":["設 L = lim_{n→∞} |aₙ|^{1/n}（可以是 ∞）。","L < 1：絕對收斂。L > 1 或 ∞：發散（從某項起 |aₙ| > 1，各項不趨近 0）。L = 1：沒有結論；p 級數全都給 1。"]},{"heading":"③ 什麼時候用","body":["aₙ 是「某個式子的 n 次方」，例如 (n/(2n + 1))ⁿ、(1 + 1/n)^{n²}/3ⁿ：開 n 次方直接把指數拿掉。","兩個好用的極限（〈數列與數列極限〉）：n^{1/n} → 1，因為 ln(n^{1/n}) = (ln n)/n → 0；常數 C > 0 時 C^{1/n} → 1。所以多項式因子開 n 次方之後都變成 1：(n³)^{1/n} = (n^{1/n})³ → 1。","有階乘的時候反而用比值判別：n! 開 n 次方不好算，比值卻能直接約分。"]},{"heading":"④ 證明與兩者的關係","body":["L < 1：取 L < r < 1，從某項起 |aₙ|^{1/n} < r，即 |aₙ| < rⁿ。Σ rⁿ 收斂，由比較判別 Σ |aₙ| 收斂。L > 1：從某項起 |aₙ| > 1，發散判別。","另外可以證明：比值的極限存在時，根值的極限也存在而且相等。所以根值判別能處理的情況至少跟比值判別一樣多，只是計算不一定比較方便。"],"collapsible":true}],"workedExamples":[{"title":"整個式子的 n 次方","prompt":"Σ_{n=1}^∞ (n/(2n + 1))ⁿ 收斂嗎？","problemId":"lec-13-q2c","steps":["|aₙ|^{1/n} = n/(2n + 1)。","→ 1/2 < 1。","絕對收斂，所以收斂。"],"answer":"收斂"},{"title":"指數是 n²","prompt":"Σ_{n=1}^∞ (1 + 1/n)^{n²}/3ⁿ 收斂嗎？","problemId":"lec-13-q2e","steps":["開 n 次方：((1 + 1/n)^{n²})^{1/n} = (1 + 1/n)ⁿ，(3ⁿ)^{1/n} = 3。","|aₙ|^{1/n} = (1 + 1/n)ⁿ/3 → e/3 ≈ 0.906 < 1（〈e 型極限〉）。","收斂。這題用比值判別會非常痛苦。"],"answer":"收斂（L = e/3）"},{"title":"多項式因子開掉","prompt":"用根值判別判斷 Σ_{n=1}^∞ n³/3ⁿ。","steps":["|aₙ|^{1/n} = (n^{1/n})³/3。","n^{1/n} → 1，所以 → 1/3 < 1。","收斂。（比值判別也做得到：((n + 1)/n)³/3 → 1/3，同一個 L。）"],"answer":"收斂（L = 1/3）"}],"pitfalls":["開 n 次方時，分母的 3ⁿ 或分子的多項式忘了一起開。","以為 n^{1/n} → ∞ 或 → 0。","L = 1 時下結論。","對含階乘的式子硬開 n 次方。"],"checks":[{"ask":"Σ (2n/(n + 1))ⁿ 是？","options":[{"label":"發散：根值 → 2 > 1","correct":true},{"label":"收斂：根值 → 1/2","why":"2n/(n + 1) 的極限是 2，不是 1/2；分子分母寫反了。"},{"label":"無法判斷：根值 → 1","why":"2n/(n + 1) → 2/1 = 2，領導係數不同，不是 1。"}]},{"ask":"lim_{n→∞} n^{1/n} = ？","options":[{"label":"1","correct":true},{"label":"∞","why":"n 雖然變大，開 n 次方壓得更兇：ln(n^{1/n}) = (ln n)/n → 0，所以 → e⁰ = 1。"},{"label":"0","why":"n ≥ 1 時 n^{1/n} ≥ 1，不可能趨近 0。"}]},{"ask":"下列哪一個最適合用根值判別？","options":[{"label":"Σ ((3n + 1)/(4n − 1))ⁿ","correct":true},{"label":"Σ n!/5ⁿ","why":"有階乘時比值判別最省事：(n + 1)/5 一步就出來；n! 開 n 次方很難算。"},{"label":"Σ (n + 1)/(n³ + 2)","why":"有理式的根值、比值都 → 1，兩個都沒結論；應該用極限比較。"}]},{"ask":"對 Σ 1/n² 用根值判別，得到？","options":[{"label":"L = 1，沒有結論","correct":true},{"label":"L = 0，收斂","why":"(1/n²)^{1/n} = 1/(n^{1/n})² → 1，不是 0。"},{"label":"L = 1/2，收斂","why":"開 n 次方不是把指數 2 除掉；(1/n²)^{1/n} → 1。"}]}],"practice":[{"id":"lec-13-q2c","core":true},{"id":"rel-adv-015","core":true},{"id":"lec-13-q2e","core":true},{"id":"lec-11-m3"},{"id":"gap-tech-005"}]},"alternating-series-test":{"id":"alternating-series-test","prerequisites":["divergence-test","partial-sums","increasing-decreasing"],"next":["absolute-convergence"],"related":["monotone-convergence-sequence","conditional-convergence","power-series-calculus"],"objectives":["說出交錯級數判別的三個條件：bₙ > 0、bₙ 遞減、bₙ → 0。","會檢查遞減（差、或 f′ ≤ 0），並在 bₙ 不 → 0 時改用發散判別。","用 |S − S_N| ≤ b_{N+1} 決定要取幾項。"],"concept":[{"heading":"① 正負交替的級數","body":["交錯級數長這樣：Σ (−1)^{n+1} bₙ = b₁ − b₂ + b₃ − b₄ + …，其中 bₙ > 0。例如交錯調和級數 1 − 1/2 + 1/3 − 1/4 + …。"]},{"heading":"② 圖像：越跳越短的來回","body":["部分和在數線上來回跳：往右 b₁、往左 b₂、往右 b₃……。如果每一跳都不比上一跳長，奇數次的落點一路往左、偶數次的一路往右，而且奇數落點永遠在偶數落點的右邊。兩組落點被夾在一起；只要跳的長度 bₙ → 0，夾住的區間就縮成一個點，那就是級數的和。"]},{"heading":"③ 定理與誤差","body":["若 (1) bₙ > 0，(2) bₙ₊₁ ≤ bₙ（從某一項開始即可），(3) lim bₙ = 0，則 Σ (−1)^{n+1} bₙ 收斂。","而且和 S 永遠夾在相鄰兩個部分和之間，所以 |S − S_N| ≤ b_{N+1}：誤差不超過第一個沒加進去的項。"]},{"heading":"④ 三個條件都要檢查","body":["bₙ 不 → 0：直接由〈發散判別〉發散，不必討論。","bₙ → 0 但不遞減：判別法不能用，級數可能發散。例如 1 − 1 + 1/2 − 1/4 + 1/3 − 1/9 + …（奇數位放 1/k、偶數位放 1/k²），每兩項的和是 1/k − 1/k²，加起來跟 Σ 1/k 一樣發散。","檢查遞減：看 bₙ₊₁ − bₙ，或令 bₙ = f(n) 看 f′(x) ≤ 0（〈增減區間〉）。"]},{"heading":"⑤ 證明","body":["偶數項部分和：S_{2k+2} = S_{2k} + (b_{2k+1} − b_{2k+2}) ≥ S_{2k}，遞增。又 S_{2k} = b₁ − (b₂ − b₃) − … − (b_{2k−2} − b_{2k−1}) − b_{2k} ≤ b₁，有上界。由〈單調收斂定理〉S_{2k} → S。奇數項 S_{2k+1} = S_{2k} + b_{2k+1} → S + 0 = S。兩組子數列都收斂到 S，整個部分和數列收斂到 S。同樣的分組也顯示 S 夾在任兩個相鄰的部分和之間，得到誤差估計。"],"collapsible":true}],"workedExamples":[{"title":"交錯調和級數","prompt":"Σ_{n=1}^∞ (−1)^{n+1}/n 收斂嗎？","steps":["bₙ = 1/n > 0。","遞減：1/(n + 1) < 1/n。","bₙ = 1/n → 0。三個條件都成立，收斂。（它的和是 ln 2，要用〈冪級數的微分與積分〉才算得出來。）"],"answer":"收斂"},{"title":"要用導數證遞減","prompt":"Σ_{n=1}^∞ (−1)ⁿ n/(n² + 1) 收斂嗎？","steps":["bₙ = n/(n² + 1) > 0，而且 → 0（分母次數較高）。","遞減不明顯（分子分母都在長）。令 f(x) = x/(x² + 1)，f′(x) = (1 − x²)/(x² + 1)²，x ≥ 1 時 ≤ 0，所以 bₙ 遞減。","三個條件成立，收斂。（這裡多一個負號 (−1)ⁿ = −(−1)^{n+1}，整個級數只是乘以 −1，不影響收斂。）"],"answer":"收斂"},{"title":"要取幾項","prompt":"S = Σ_{n=1}^∞ (−1)^{n+1}/n³。要保證 |S − Sₙ| < 0.01，n 至少多少？","problemId":"lec-13-q3b","steps":["bₙ = 1/n³ 為正、遞減、→ 0，誤差估計可以用：|S − Sₙ| ≤ bₙ₊₁ = 1/(n + 1)³。","要 1/(n + 1)³ < 0.01，即 (n + 1)³ > 100。4³ = 64 不夠，5³ = 125 可以，所以 n + 1 ≥ 5。","n = 4。此時 S₄ = 1 − 1/8 + 1/27 − 1/64 = 1549/1728 ≈ 0.8964，真正的 S ≈ 0.9015，誤差約 0.005 < 0.01。"],"answer":"4"}],"pitfalls":["只檢查 bₙ → 0，沒檢查遞減。","bₙ 不 → 0 時還在用交錯級數判別。","誤差估計用了 b_N 而不是 b_{N+1}。","以為交錯級數判別也說明了「絕對收斂」：它只說收斂。"],"checks":[{"ask":"Σ (−1)ⁿ/√n 是？","options":[{"label":"收斂","correct":true},{"label":"發散，因為 Σ 1/√n 發散","why":"那是取絕對值之後的級數。交錯號讓正負互相抵銷，bₙ = 1/√n 遞減到 0，所以收斂。"},{"label":"無法判斷","why":"bₙ = 1/√n 為正、遞減、→ 0，三個條件都成立。"}]},{"ask":"Σ (−1)ⁿ n/(n + 1) 是？","options":[{"label":"發散","correct":true},{"label":"由交錯級數判別，收斂","why":"第三個條件不成立：bₙ = n/(n + 1) → 1，不是 0。"},{"label":"正負交替，所以一定收斂","why":"交替不夠；各項的大小不趨近 0，由發散判別發散。"}]},{"ask":"交錯級數判別的條件都成立，用 S_N 近似 S，誤差不超過？","options":[{"label":"b_{N+1}","correct":true},{"label":"b_N","why":"b_N 已經加進 S_N 了；控制誤差的是第一個還沒加的項。"},{"label":"1/N","why":"跟 bₙ 無關的猜測；誤差估計是 b_{N+1}，對 bₙ = 1/n 時才剛好是 1/(N + 1)。"}]},{"ask":"bₙ > 0、bₙ → 0，但 bₙ 不遞減。Σ (−1)^{n+1} bₙ？","options":[{"label":"判別法不能用，要另外判斷","correct":true},{"label":"一定收斂","why":"反例：1 − 1 + 1/2 − 1/4 + 1/3 − 1/9 + … 每兩項和是 1/k − 1/k²，加總發散。"},{"label":"一定發散","why":"也可能收斂：bₙ = (2 + (−1)ⁿ)/n² 不遞減，但 Σ bₙ ≤ Σ 3/n² 收斂，交錯版本當然也收斂。"}]}],"practice":[{"id":"lec-13-m5","core":true},{"id":"lec-13-q3b","core":true},{"id":"sg-est-002","core":true},{"id":"lec-13-m4","core":true},{"id":"lec-13-q3c"},{"id":"an-sr-001"},{"id":"sg-est-007"}]},"absolute-convergence":{"id":"absolute-convergence","prerequisites":["comparison-test","alternating-series-test"],"next":["conditional-convergence"],"related":["ratio-test","root-test","p-series","power-series-calculus","rearrangement"],"objectives":["說出定義：Σ |aₙ| 收斂時，Σ aₙ 絕對收斂。","使用定理「絕對收斂 ⇒ 收斂」，把正項級數的判別法搬到任意正負號的級數上。","知道比值、根值判別給的 L < 1 其實是絕對收斂。"],"concept":[{"heading":"① 定義","body":["把每一項都取絕對值：若 Σ |aₙ| 收斂，就說 Σ aₙ 絕對收斂。","Σ |aₙ| 是正項級數，所以〈比較判別〉、〈p 級數〉、〈比值判別〉這些只適用於正項的工具全都能用。"]},{"heading":"② 定理：絕對收斂 ⇒ 收斂","body":["直觀，不是證明：把負號加回去只會讓項互相抵銷。連「全部取正、毫不抵銷」都加得完，有抵銷的當然也加得完。","這句話讓我們可以處理正負號不規則的級數（例如 cos n/n²），那種級數〈交錯級數判別〉用不上，因為它的正負不是一正一負輪流。"]},{"heading":"③ 反過來不成立","body":["Σ |aₙ| 發散時，Σ aₙ 可能收斂也可能發散。交錯調和級數 Σ (−1)^{n+1}/n 收斂，但 Σ 1/n 發散。這種「收斂但不絕對收斂」的情況叫條件收斂，下一課〈條件收斂〉專門處理。"]},{"heading":"④ 比值與根值判別","body":["比值判別和根值判別看的都是 |aₙ|，所以 L < 1 時得到的結論其實是「絕對收斂」，比單純收斂更強。"]},{"heading":"⑤ 為什麼「絕對」值得特別強調","body":["絕對收斂的級數像有限和一樣好用：任意調換項的順序，和都不變；兩個絕對收斂級數也可以放心地逐項相乘。這些看似理所當然的操作，對「收斂但不絕對收斂」的級數會出錯，例如把交錯調和級數的項重新排列，和可以變成別的數（〈重排的概念〉）。","所以判斷一個有正有負的級數時，第一步通常是先看 Σ |aₙ|：收斂的話就是最好的情況，可以停了。"]},{"heading":"⑥ 證明","body":["對每個 n，−|aₙ| ≤ aₙ ≤ |aₙ|，所以 0 ≤ aₙ + |aₙ| ≤ 2|aₙ|。Σ 2|aₙ| 收斂，由比較判別 Σ (aₙ + |aₙ|) 收斂。兩個收斂級數相減仍收斂：Σ aₙ = Σ (aₙ + |aₙ|) − Σ |aₙ|。"],"collapsible":true}],"workedExamples":[{"title":"正負號不規則","prompt":"Σ_{n=1}^∞ (cos n)/n² 收斂嗎？","problemId":"lec-13-q1c","steps":["cos n 的正負沒有規律（cos 1 > 0、cos 2 < 0、cos 3 < 0、cos 4 < 0、cos 5 > 0……），不是交錯級數。","看絕對值：|cos n/n²| ≤ 1/n²，而 Σ 1/n² 收斂。由比較判別 Σ |cos n|/n² 收斂。","所以 Σ cos n/n² 絕對收斂，因此收斂。"],"answer":"絕對收斂"},{"title":"交錯級數也可以絕對收斂","prompt":"Σ_{n=1}^∞ (−1)ⁿ/n² 是絕對收斂、條件收斂還是發散？","problemId":"lec-13-q1b","steps":["取絕對值：Σ 1/n²，p = 2 > 1，收斂。","所以絕對收斂。不需要再用交錯級數判別。"],"answer":"絕對收斂"},{"title":"用比值判別得到絕對收斂","prompt":"Σ_{n=1}^∞ (−1)^{n+1} n/2ⁿ 收斂嗎？","problemId":"uni-ser-015","steps":["看 |aₙ| = n/2ⁿ。比值 |aₙ₊₁|/|aₙ| = ((n + 1)/n) · (1/2) → 1/2 < 1。","所以 Σ n/2ⁿ 收斂，原級數絕對收斂。","（它的和是 2/9，要用〈冪級數的微分與積分〉才算得出來。）"],"answer":"絕對收斂"}],"pitfalls":["對正負號不規則的級數用交錯級數判別。","Σ |aₙ| 發散就說 Σ aₙ 發散。","比較判別直接用在有負項的 aₙ 上，沒有先取絕對值。","以為絕對收斂和收斂是同一件事。"],"checks":[{"ask":"Σ |aₙ| 收斂，則 Σ aₙ：","options":[{"label":"一定收斂","correct":true},{"label":"不一定收斂","why":"絕對收斂推得出收斂：0 ≤ aₙ + |aₙ| ≤ 2|aₙ|，用比較判別再相減。"},{"label":"一定發散","why":"沒有理由；Σ (−1)ⁿ/n² 就是絕對收斂又收斂的例子。"}]},{"ask":"Σ (sin n)/n³ 是？","options":[{"label":"絕對收斂","correct":true},{"label":"用交錯級數判別，收斂","why":"sin n 的正負不是一正一負輪流，交錯級數判別用不上；要看 |sin n|/n³ ≤ 1/n³。"},{"label":"發散，因為 sin n 沒有極限","why":"各項 sin n/n³ → 0；而且絕對值被 1/n³ 壓住，收斂。"}]},{"ask":"Σ |aₙ| 發散，則 Σ aₙ：","options":[{"label":"無法判斷","correct":true},{"label":"一定發散","why":"交錯調和級數：Σ 1/n 發散，Σ (−1)^{n+1}/n 卻收斂。"},{"label":"一定收斂","why":"Σ 1 的各項都是正的，絕對值發散，本身也發散。"}]},{"ask":"對 Σ aₙ 用比值判別得到 L = 1/3，結論是？","options":[{"label":"絕對收斂","correct":true},{"label":"條件收斂","why":"比值判別看的是 |aₙ|，L < 1 說明 Σ |aₙ| 收斂，這是絕對收斂。"},{"label":"只知道 Σ |aₙ| 收斂，Σ aₙ 本身不確定","why":"絕對收斂推得出收斂，所以 Σ aₙ 也收斂。"}]}],"practice":[{"id":"lec-13-q1b","core":true},{"id":"lec-13-q1c","core":true},{"id":"fd-ser-007","core":true},{"id":"uni-ser-015"},{"id":"fd-serx-405"},{"id":"burst-boss-ser-004","challenge":true,"note":"挑戰：絕對收斂的交錯級數，和可以從 Σ 1/n² = π²/6 拆出來。"}]},"conditional-convergence":{"id":"conditional-convergence","prerequisites":["absolute-convergence","alternating-series-test"],"next":["rearrangement"],"related":["limit-comparison-test","p-series","divergence-test"],"objectives":["說出條件收斂的定義：Σ aₙ 收斂，但 Σ |aₙ| 發散。","照固定的順序把一個級數分類成絕對收斂、條件收斂或發散。","記住 Σ (−1)ⁿ/nᵖ 的三段：p > 1 絕對收斂，0 < p ≤ 1 條件收斂，p ≤ 0 發散。"],"concept":[{"heading":"① 定義","body":["Σ aₙ 收斂，但 Σ |aₙ| 發散，就叫條件收斂。它的收斂完全靠正負抵銷：拿掉負號就加不完了。標準例子是交錯調和級數 Σ (−1)^{n+1}/n。"]},{"heading":"② 分類的順序","body":["拿到一個有正有負的級數：","1. 各項 → 0 嗎？不是 → 發散（〈發散判別〉），結束。","2. 看 Σ |aₙ|，用正項級數的判別法（p 級數、比較、〈極限比較判別〉、比值）。收斂 → 絕對收斂，結束。","3. Σ |aₙ| 發散時，回頭看 Σ aₙ 本身，通常用交錯級數判別。收斂 → 條件收斂；否則發散。","順序很重要：先檢查絕對收斂，因為它是比較強、也比較好的結論。"]},{"heading":"③ 一整族的答案","body":["Σ (−1)ⁿ/nᵖ：","p > 1：Σ 1/nᵖ 收斂，絕對收斂。","0 < p ≤ 1：Σ 1/nᵖ 發散（〈p 級數〉），但 1/nᵖ 遞減到 0，交錯級數判別給收斂，所以條件收斂。","p ≤ 0：各項大小不趨近 0，發散。"]},{"heading":"④ 為什麼說它「有條件」","body":["直觀，不是證明：條件收斂的級數，正項部分加起來是 +∞，負項部分加起來是 −∞（如果有一邊有限，另一邊也會有限，整個就絕對收斂了）。它能收斂，靠的是「一正一負按某個順序」交替。換一個順序，兩個無限大抵銷的方式就變了，和也可能跟著變。這就是下一課〈重排的概念〉。"]}],"workedExamples":[{"title":"p = 1/2","prompt":"Σ_{n=1}^∞ (−1)ⁿ/√n 是絕對收斂、條件收斂還是發散？","problemId":"lec-13-q1a","steps":["各項大小 1/√n → 0，第 1 步通過。","Σ |aₙ| = Σ 1/√n，p = 1/2 ≤ 1，發散。不是絕對收斂。","交錯級數判別：1/√n > 0、遞減、→ 0，所以 Σ (−1)ⁿ/√n 收斂。","條件收斂。（和約為 −0.605。）"],"answer":"條件收斂"},{"title":"絕對值用極限比較","prompt":"Σ_{n=1}^∞ (−1)ⁿ n/(n² + 1) 是絕對收斂、條件收斂還是發散？","problemId":"lec-13-q1d","steps":["各項大小 n/(n² + 1) → 0。","Σ n/(n² + 1)：跟 1/n 做極限比較，比值 n²/(n² + 1) → 1，而 Σ 1/n 發散，所以 Σ |aₙ| 發散。","交錯級數判別：〈交錯級數判別〉的範例已證明 n/(n² + 1) 從 n = 1 起遞減到 0，所以原級數收斂。","條件收斂。"],"answer":"條件收斂"},{"title":"整族分類","prompt":"對哪些實數 p，Σ_{n=1}^∞ (−1)ⁿ/nᵖ 條件收斂？","problemId":"lec-13-q4a","steps":["p > 1：Σ 1/nᵖ 收斂，絕對收斂，不算條件收斂。","0 < p ≤ 1：絕對值發散；1/nᵖ 遞減到 0，交錯級數收斂。條件收斂。","p ≤ 0：|(−1)ⁿ/nᵖ| = n^{−p} ≥ 1，不趨近 0，發散。","答案：0 < p ≤ 1，也就是區間 (0, 1]。"],"answer":"(0, 1]"}],"pitfalls":["Σ |aₙ| 發散就直接說發散，忘了檢查 Σ aₙ 本身。","交錯級數判別成立就說「絕對收斂」：它只給收斂。","p 的範圍端點錯：p = 1 是條件收斂，p = 0 是發散。","跳過發散判別，對各項不趨近 0 的級數做了一堆白工。"],"checks":[{"ask":"條件收斂的意思是？","options":[{"label":"Σ aₙ 收斂，但 Σ |aₙ| 發散","correct":true},{"label":"Σ aₙ 發散，但 Σ |aₙ| 收斂","why":"不可能發生：Σ |aₙ| 收斂就推得出 Σ aₙ 收斂。"},{"label":"Σ aₙ 與 Σ |aₙ| 都收斂","why":"那是絕對收斂，比條件收斂更強。"}]},{"ask":"Σ (−1)ⁿ/n^{0.5} 是？","options":[{"label":"條件收斂","correct":true},{"label":"絕對收斂","why":"取絕對值是 Σ 1/√n，p = 1/2 ≤ 1，發散。"},{"label":"發散","why":"1/√n 遞減到 0，交錯級數判別給收斂。"}]},{"ask":"Σ (−1)ⁿ/n² 是？","options":[{"label":"絕對收斂","correct":true},{"label":"條件收斂","why":"取絕對值 Σ 1/n² 已經收斂，屬於更強的絕對收斂。"},{"label":"發散","why":"各項 → 0，而且絕對值級數收斂。"}]},{"ask":"Σ (−1)ⁿ (n + 1)/n 是？","options":[{"label":"發散","correct":true},{"label":"條件收斂","why":"各項大小 (n + 1)/n → 1，不是 0；發散判別第一步就出局。"},{"label":"絕對收斂","why":"Σ (n + 1)/n 的各項 → 1，絕對值級數顯然發散。"}]}],"practice":[{"id":"gap-ser-cond-001","core":true},{"id":"lec-13-q1a","core":true},{"id":"fd-serx-208","core":true},{"id":"lec-13-q1d","core":true},{"id":"mob-conv-003"},{"id":"lec-13-m1"},{"id":"rel-hard-ser-011"},{"id":"lec-13-q4a","challenge":true,"note":"挑戰：答案是一個區間，三段都要想清楚，尤其端點 p = 1 與 p = 0。"}]},"rearrangement":{"id":"rearrangement","prerequisites":["conditional-convergence"],"next":["power-series"],"related":["absolute-convergence"],"objectives":["說出重排的意思：同樣的項，每一項恰好用一次，換一個順序。","知道絕對收斂的級數怎麼重排和都不變；條件收斂的級數可以被重排成任何和（Riemann 重排定理，不證）。","能說明「先加正項超過目標、再加負項跌破目標」的構造想法。"],"concept":[{"heading":"① 什麼是重排","body":["把級數的項換個順序：每一項都要出現、而且只出現一次。有限和怎麼排都一樣（加法交換律），但無窮級數的和是部分和的極限，換了順序，部分和就是另一串數，極限不一定相同。"]},{"heading":"② 絕對收斂：怎麼排都一樣","body":["若 Σ aₙ 絕對收斂，它的任何重排也收斂，而且和不變。這是絕對收斂「像有限和一樣好用」的主要原因（〈絕對收斂〉）。這裡不證明。"]},{"heading":"③ 條件收斂：想要多少就排成多少","body":["Riemann 重排定理：若 Σ aₙ 條件收斂，則對任何實數 T，都存在一種重排使和等於 T；也存在重排使它發散到 +∞ 或 −∞。這裡只講想法，不證。","構造的想法（不是完整證明）：條件收斂時，正項加起來是 +∞、負項加起來是 −∞，而各項 → 0。所以：先拿正項，直到部分和超過 T；再拿負項，直到跌破 T；再拿正項……。正項加不完、負項也加不完，每一輪都做得到。每次越過 T 的超出量不超過最後拿的那一項，而項 → 0，所以部分和被拉向 T。"]},{"heading":"④ 實際的教訓","body":["計算條件收斂的級數時，不能隨意調換順序、把正項和負項分開加，或改變分組方式，否則可能得到錯的數字。範例 1、2 是同一組項排出三個不同的和：ln 2、½ ln 2、(3/2) ln 2。"]}],"workedExamples":[{"title":"一正兩負：和變成一半","prompt":"把交錯調和級數重排成 1 − 1/2 − 1/4 + 1/3 − 1/6 − 1/8 + 1/5 − 1/10 − 1/12 + …（一個奇數分母的正項，接兩個偶數分母的負項）。求它的和。","steps":["每三項一組，第 k 組是 1/(2k − 1) − 1/(2(2k − 1)) − 1/(4k)。","前兩項合併：1/(2k − 1) − 1/(4k − 2) = 1/(2(2k − 1))。所以一組 = 1/(2(2k − 1)) − 1/(4k) = ½(1/(2k − 1) − 1/(2k))。","各組加起來是 ½(1 − 1/2 + 1/3 − 1/4 + …) = ½ ln 2。（每組只有三項而且項 → 0，所以分組後的極限就是重排後級數的和。）","原本的順序和是 ln 2，同樣的項換了順序，變成一半。"],"answer":"½ ln 2"},{"title":"兩正一負：和變大","prompt":"重排成 1 + 1/3 − 1/2 + 1/5 + 1/7 − 1/4 + …（兩個正項接一個負項）。求它的和。","problemId":"an-sr-004","steps":["令 S = 1 − 1/2 + 1/3 − 1/4 + … = ln 2。則 ½S = 1/2 − 1/4 + 1/6 − 1/8 + …。","把 ½S 寫成 0 + 1/2 + 0 − 1/4 + 0 + 1/6 + 0 − 1/8 + …，跟 S 逐項相加（兩個收斂級數可以逐項相加）：1 + 0 + 1/3 − 1/2 + 1/5 + 0 + 1/7 − 1/4 + …。","去掉那些 0（部分和只是少了幾個重複值，極限不變），正好是題目的排法。","和 = S + ½S = (3/2) ln 2 ≈ 1.04。"],"answer":"(3/2) ln 2"},{"title":"絕對收斂：怎麼排都一樣","prompt":"Σ_{n=1}^∞ (−1)^{n+1}/n² = π²/12。先把正項全加、再減掉負項全部，會得到同一個數嗎？","steps":["Σ 1/n² 收斂，所以這是絕對收斂，任何重排都不改變和。","正項：Σ 1/(2k − 1)² = π²/8；負項：Σ 1/(2k)² = (1/4)(π²/6) = π²/24。兩者都有限。","π²/8 − π²/24 = π²/12，一致。對照：交錯調和級數的正項和負項分開加都是無限大，根本不能這樣做。"],"answer":"會，都是 π²/12"}],"pitfalls":["對條件收斂的級數把正負項分開加。","以為重排只要「項一樣」，和就一定一樣。","以為 Riemann 重排定理也適用於絕對收斂的級數。","把「加括號分組」和「重排」混為一談：分組不改順序，但對發散級數也會出問題。"],"checks":[{"ask":"絕對收斂的級數任意重排之後？","options":[{"label":"仍收斂，而且和不變","correct":true},{"label":"仍收斂，但和可能改變","why":"和會改變的只有條件收斂的級數；絕對收斂的級數像有限和一樣，怎麼排都一樣。"},{"label":"可能發散","why":"絕對收斂的級數重排後仍然絕對收斂，不會發散。"}]},{"ask":"Riemann 重排定理說，條件收斂的級數經過重排可以？","options":[{"label":"收斂到任何指定的實數，也可以發散","correct":true},{"label":"只能變成發散，不能變成別的和","why":"定理說的是任何實數都排得出來，例如交錯調和級數可以排成 ½ ln 2 或 (3/2) ln 2。"},{"label":"和永遠不變","why":"那是絕對收斂的性質；範例 1、2 就是反例。"}]},{"ask":"為什麼不能把交錯調和級數的正項、負項分開加？","options":[{"label":"正項的和是 +∞，負項的和是 −∞，分開加得到 ∞ − ∞","correct":true},{"label":"因為各項不趨近 0","why":"各項 ±1/n 確實 → 0；問題在於它只是條件收斂。"},{"label":"因為交錯調和級數發散","why":"它收斂到 ln 2，只是不絕對收斂。"}]},{"ask":"1 − 1/2 − 1/4 + 1/3 − 1/6 − 1/8 + … 的和是？","options":[{"label":"½ ln 2","correct":true},{"label":"ln 2","why":"項跟交錯調和級數一樣，但順序不同；條件收斂的級數換了順序，和會變。"},{"label":"發散","why":"每三項一組是 ½(1/(2k − 1) − 1/(2k))，加起來收斂到 ½ ln 2。"}]}],"practice":[{"id":"an-sr-004","core":true}]},"power-series":{"id":"power-series","prerequisites":["geometric-series","absolute-convergence"],"next":["radius-of-convergence"],"related":["taylor-polynomial"],"objectives":["認得冪級數 Σ cₙ(x − a)ⁿ 的中心 a 與係數 cₙ，知道它對每個 x 是一個數值級數。","以 Σ xⁿ = 1/(1 − x)（|x| < 1）為原型，分清楚「函數的定義域」與「級數代表它的範圍」。","用代換從幾何級數造出新的冪級數，並寫出它成立的範圍。"],"concept":[{"heading":"① 無限長的多項式","body":["冪級數長這樣：Σ_{n=0}^∞ cₙ(x − a)ⁿ = c₀ + c₁(x − a) + c₂(x − a)² + …。a 是中心，cₙ 是係數。","給定一個 x，它就變成一個普通的數值級數，可能收斂也可能發散。讓它收斂的 x 收集起來，級數就在那些 x 上定義了一個函數 f(x)。它的部分和都是多項式，所以冪級數可以想成「無限長的多項式」。"],"tex":["f(x)=\\sum_{n=0}^{\\infty} c_n (x-a)^n"]},{"heading":"② 原型：幾何級數","body":["Σ xⁿ = 1 + x + x² + … 是中心 0、所有係數都是 1 的冪級數。由〈幾何級數〉，|x| < 1 時它等於 1/(1 − x)，|x| ≥ 1 時發散。","注意兩者的差別：函數 1/(1 − x) 除了 x = 1 到處有定義，但級數只在 (−1, 1) 上代表它。在 x = 2，函數值是 −1，級數 1 + 2 + 4 + … 卻發散。"]},{"heading":"③ 一定收斂的地方","body":["x = a 時，除了第一項之外全部是 0，級數的和就是 c₀。所以每個冪級數至少在中心收斂。它還在哪裡收斂，下一課〈收斂半徑〉會說：答案永遠是以 a 為中心的一段區間。"]},{"heading":"④ 從幾何級數造新級數","body":["1/(1 − u) = Σ uⁿ（|u| < 1）裡的 u 可以換成任何式子，條件跟著換：","u = −x²：1/(1 + x²) = Σ (−1)ⁿ x²ⁿ，條件 |x²| < 1，即 |x| < 1。","u = 3x：1/(1 − 3x) = Σ 3ⁿxⁿ，條件 |x| < 1/3。","前面乘上 x 之類的式子，只是把每一項的次方加一，成立範圍不變。"]}],"workedExamples":[{"title":"中心不在 0","prompt":"Σ_{n=0}^∞ (x + 2)ⁿ/3ⁿ 在哪些 x 收斂？和是多少？","steps":["寫成 Σ ((x + 2)/3)ⁿ，中心 a = −2，公比 u = (x + 2)/3。","收斂 ⇔ |x + 2| < 3 ⇔ −5 < x < 1。","和 = 1/(1 − (x + 2)/3) = 3/(3 − x − 2) = 3/(1 − x)。","檢查 x = −1：級數是 Σ (1/3)ⁿ = 3/2，而 3/(1 − (−1)) = 3/2。"],"answer":"−5 < x < 1 時收斂，和為 3/(1 − x)"},{"title":"代換 u = −x²","prompt":"寫出 1/(1 + x²) 的冪級數，以及它成立的範圍。","problemId":"lec-14-m4","steps":["1/(1 + x²) = 1/(1 − (−x²))，令 u = −x²。","= Σ (−x²)ⁿ = Σ (−1)ⁿ x²ⁿ = 1 − x² + x⁴ − x⁶ + …。","條件 |−x²| < 1，即 |x| < 1。注意 1/(1 + x²) 對所有實數都有定義，但這個級數只在 (−1, 1) 收斂。"],"answer":"Σ (−1)ⁿ x²ⁿ，|x| < 1"},{"title":"先湊出 1 − u","prompt":"寫出 x/(4 + x²) 的冪級數，以及它成立的範圍。","problemId":"lec-14-q2a","steps":["分母提出 4：x/(4 + x²) = (x/4) · 1/(1 + x²/4) = (x/4) · 1/(1 − (−x²/4))。","u = −x²/4：= (x/4) Σ (−1)ⁿ x²ⁿ/4ⁿ = Σ (−1)ⁿ x^{2n+1}/4^{n+1}。","條件 |x²/4| < 1，即 |x| < 2。"],"answer":"Σ (−1)ⁿ x^{2n+1}/4^{n+1}，|x| < 2"}],"pitfalls":["把 (x + 2)ⁿ 的中心讀成 2。","以為函數有定義的地方，冪級數就一定收斂。","代換之後忘了跟著換收斂條件。","分母不是 1 − u 的形式就直接套，沒有先提出常數。"],"checks":[{"ask":"Σ n(x − 3)ⁿ/2ⁿ 的中心是？","options":[{"label":"3","correct":true},{"label":"−3","why":"(x − a)ⁿ 的中心是 a；(x − 3) 的中心是 3，(x + 3) 才是 −3。"},{"label":"0","why":"只有寫成 Σ cₙxⁿ 時中心才是 0。"}]},{"ask":"Σ_{n=0}^∞ xⁿ 在 x = 2 的值是？","options":[{"label":"發散，沒有值","correct":true},{"label":"−1，因為 1/(1 − 2) = −1","why":"1/(1 − x) 在 x = 2 有定義，但級數只在 |x| < 1 代表它；1 + 2 + 4 + … 發散。"},{"label":"2","why":"級數的和不是代入一項；1 + 2 + 4 + 8 + … 一路往上衝。"}]},{"ask":"每一個冪級數 Σ cₙ(x − a)ⁿ 一定在哪裡收斂？","options":[{"label":"x = a","correct":true},{"label":"x = 0","why":"中心不是 0 時，x = 0 可能落在收斂範圍外。一定收斂的是中心 a。"},{"label":"所有實數 x","why":"Σ n! xⁿ 只在 x = 0 收斂。"}]},{"ask":"1/(1 − x²) 的冪級數是？","options":[{"label":"Σ x²ⁿ，|x| < 1","correct":true},{"label":"Σ (−1)ⁿ x²ⁿ，|x| < 1","why":"那是 1/(1 + x²)。這裡 u = x²，沒有負號。"},{"label":"Σ x²ⁿ，|x| < 1/2","why":"條件是 |x²| < 1，等於 |x| < 1，不是把 1 除以 2。"}]}],"practice":[{"id":"lec-12-q1d","core":true},{"id":"lec-14-m4","core":true},{"id":"lec-14-q2a","core":true},{"id":"exam-ser-019"},{"id":"tr-val-006"}]},"radius-of-convergence":{"id":"radius-of-convergence","prerequisites":["power-series","ratio-test","root-test"],"next":["interval-of-convergence"],"related":["sequence-limit"],"objectives":["說出冪級數收斂範圍的三種可能：只有中心（R = 0）、全部實數（R = ∞）、或以中心為圓心半徑 R 的區間。","用比值（或根值）判別對整個項做計算，求出 R。","處理只有偶次方的級數，以及 R = 0、R = ∞ 的情況。"],"concept":[{"heading":"① 三種可能，沒有第四種","body":["冪級數 Σ cₙ(x − a)ⁿ 的收斂範圍只有三種樣子：","R = 0：只在 x = a 收斂。R = ∞：所有實數都絕對收斂。0 < R < ∞：|x − a| < R 時絕對收斂，|x − a| > R 時發散；|x − a| = R 的兩個端點，定理什麼都不說，要各自檢查（〈收斂區間〉）。","這個 R 叫收斂半徑。收斂範圍不會是兩段分開的區間，也不會只在中心的一側。"]},{"heading":"② 怎麼算：對整個項用比值判別","body":["把 x 當成固定的數，對 Σ |cₙ(x − a)ⁿ| 用〈比值判別〉。","若 |cₙ₊₁/cₙ| → L，比值的極限是 L|x − a|。要它 < 1，得 |x − a| < 1/L，所以 R = 1/L。L = 0 時 R = ∞；L = ∞ 時 R = 0。","係數是「某某的 n 次方」時，改用〈根值判別〉：|cₙ|^{1/n} → L，一樣 R = 1/L。"],"tex":["\\left|\\frac{c_{n+1}(x-a)^{n+1}}{c_n (x-a)^{n}}\\right| \\to L\\,\\lvert x-a\\rvert<1 \\iff \\lvert x-a\\rvert<\\frac{1}{L}"]},{"heading":"③ 兩個常見的細節","body":["多項式因子不影響 R：Σ n⁵xⁿ、Σ xⁿ/n² 的 R 都是 1，因為 (n + 1)⁵/n⁵ → 1（或 n^{1/n} → 1）。真正決定 R 的是指數型的部分（3ⁿ、n! 之類）。","只有偶次方（例如 Σ x²ⁿ/9ⁿ）時，不要套 cₙ₊₁/cₙ：奇數次的係數是 0，比值沒有意義。直接對整個項算比值：|x²ⁿ⁺²/9ⁿ⁺¹| ÷ |x²ⁿ/9ⁿ| = x²/9 < 1，得 |x| < 3。"]},{"heading":"④ 為什麼只有三種","body":["關鍵引理：若級數在某個 x₀ ≠ a 收斂，則所有 |x − a| < |x₀ − a| 的 x 都絕對收斂。理由：收斂表示各項 cₙ(x₀ − a)ⁿ → 0，所以有界，|cₙ(x₀ − a)ⁿ| ≤ M。於是 |cₙ(x − a)ⁿ| ≤ M · rⁿ，其中 r = |x − a|/|x₀ − a| < 1，跟幾何級數比較即得。收斂的點會把整個更靠近中心的範圍「拉進來」，取這些 |x₀ − a| 的最小上界就是 R。"],"collapsible":true}],"workedExamples":[{"title":"標準題","prompt":"求 Σ_{n=1}^∞ xⁿ/(n · 3ⁿ) 的收斂半徑。","problemId":"cx-smid-007","steps":["整個項的比值：|xⁿ⁺¹/((n + 1)3ⁿ⁺¹)| ÷ |xⁿ/(n · 3ⁿ)| = (n/(n + 1)) · |x|/3。","n → ∞：→ |x|/3。要 |x|/3 < 1，得 |x| < 3。","R = 3。分母的 n 不影響半徑，決定的是 3ⁿ。"],"answer":"R = 3"},{"title":"兩個極端","prompt":"求 Σ n! xⁿ 與 Σ xⁿ/n! 的收斂半徑。","problemId":"lec-14-m2","steps":["Σ n! xⁿ：比值 (n + 1)! |x|ⁿ⁺¹/(n! |x|ⁿ) = (n + 1)|x|。只要 x ≠ 0 就 → ∞ > 1，發散。R = 0。","Σ xⁿ/n!：比值 |x|/(n + 1)。不管 x 是多少都 → 0 < 1，收斂。R = ∞。","階乘在分子還是分母，決定了半徑是 0 還是 ∞。"],"answer":"R = 0；R = ∞"},{"title":"階乘的比值","prompt":"求 Σ_{n=0}^∞ ((2n)!/(n!)²) xⁿ 的收斂半徑。","problemId":"rel-hard-ser-001","steps":["cₙ₊₁/cₙ = ((2n + 2)!/((n + 1)!)²) · ((n!)²/(2n)!) = (2n + 2)(2n + 1)/(n + 1)²。","→ 4（分子分母都是二次，領導係數 4 與 1）。","R = 1/4。"],"answer":"R = 1/4"}],"pitfalls":["把 R 寫成 L 而不是 1/L。","只有偶次方時還用 cₙ₊₁/cₙ。","以為多項式因子（n、n²）會改變 R。","以為 |x − a| = R 的端點也由比值判別決定。"],"checks":[{"ask":"Σ n xⁿ/5ⁿ 的收斂半徑是？","options":[{"label":"5","correct":true},{"label":"1/5","why":"比值 → |x|/5，要 < 1 得 |x| < 5。L = 1/5 是比值的係數，R 是它的倒數。"},{"label":"1","why":"n 這個多項式因子不影響 R，但 5ⁿ 會。"}]},{"ask":"Σ x²ⁿ/(n² 9ⁿ) 的收斂半徑是？","options":[{"label":"3","correct":true},{"label":"9","why":"每一項是 (x²)ⁿ，比值 → x²/9，條件是 x² < 9，也就是 |x| < 3。"},{"label":"1/9","why":"R 是 x 能走多遠；x²/9 < 1 給的是 |x| < 3。"}]},{"ask":"某冪級數 Σ cₙxⁿ 的收斂半徑 R = 2。在 x = 3？","options":[{"label":"發散","correct":true},{"label":"收斂","why":"|x| > R 時一定發散，這是定理的一部分。"},{"label":"要另外檢查","why":"需要另外檢查的只有 |x| = R 的兩個端點；x = 3 在外面，一定發散。"}]},{"ask":"Σ 3ⁿ xⁿ/n² 的收斂半徑是？","options":[{"label":"1/3","correct":true},{"label":"3","why":"3ⁿ 在係數裡（分子），比值 → 3|x|，要 < 1 得 |x| < 1/3。"},{"label":"1","why":"n² 不影響，但 3ⁿ 會讓半徑縮成 1/3。"}]}],"practice":[{"id":"lec-14-m1","core":true},{"id":"rel-basic-022","core":true},{"id":"cx-smid-007","core":true},{"id":"exam-ser-001","core":true},{"id":"lec-14-m2","core":true},{"id":"lec-14-m3","core":true},{"id":"ser-039"},{"id":"uni-ser-019"},{"id":"uni-ser-014"},{"id":"ser-030"},{"id":"gap-ser-root-001"},{"id":"gap-ser-root-002"},{"id":"cx-smid-006"},{"id":"rel-hard-ser-001"},{"id":"rel-hard-ser-012","challenge":true,"note":"挑戰：係數 nⁿ/n!，比值化成 (1 + 1/n)ⁿ → e，R = 1/e。"},{"id":"an-ls-004","challenge":true,"note":"挑戰：係數奇偶交錯，比值沒有極限；要用根值的上極限，取比較大的那個。"}]},"interval-of-convergence":{"id":"interval-of-convergence","prerequisites":["radius-of-convergence","conditional-convergence"],"next":["power-series-calculus"],"related":["p-series","alternating-series-test","divergence-test"],"objectives":["求出 R 之後，把兩個端點分別代回，變成數值級數各自判斷。","知道端點上比值判別一定給 L = 1，要改用 p 級數、交錯級數判別或發散判別。","寫出四種可能的區間 (a, b)、[a, b)、(a, b]、[a, b] 之一，並能說出端點是絕對還是條件收斂。"],"concept":[{"heading":"① 收斂半徑只回答了一半","body":["〈收斂半徑〉告訴我們 |x − a| < R 收斂、|x − a| > R 發散，但兩個端點 x = a − R、x = a + R 什麼都沒說。端點上比值的極限剛好是 1，比值判別在那裡一定失效。","所以端點要「代進去」：x 換成具體的數，冪級數就變成一個普通的數值級數，再用前面學過的工具判斷。"]},{"heading":"② 端點常見的三種樣子","body":["代進去以後，通常會變成：p 級數（看 p 是否 > 1，〈p 級數〉）；交錯的 p 級數（用〈交錯級數判別〉，可能條件收斂）；各項不趨近 0 的級數（〈發散判別〉）。","兩個端點的結果可以不一樣，所以收斂區間有四種可能：(a − R, a + R)、[a − R, a + R)、(a − R, a + R]、[a − R, a + R]。"]},{"heading":"③ 完整流程","body":["1. 對整個項用比值（或根值）判別，得到 |x − a| < R。","2. 寫出兩個端點 a ± R。","3. 每個端點代回去，化簡成數值級數，判斷收斂或發散（有需要時說明絕對或條件收斂）。","4. 寫出區間，收斂的端點用中括號。","中心不在 0 的時候，例如 (2x − 1)ⁿ = 2ⁿ(x − 1/2)ⁿ，先把它化成 (x − a) 的形式，中心與半徑才不會讀錯。"]}],"workedExamples":[{"title":"一邊收斂一邊發散","prompt":"求 Σ_{n=1}^∞ xⁿ/n 的收斂區間。","problemId":"lec-14-m5","steps":["比值：(n/(n + 1))|x| → |x|，R = 1，中心 0。","x = 1：Σ 1/n，調和級數，發散。","x = −1：Σ (−1)ⁿ/n，1/n 遞減到 0，交錯級數判別給收斂（條件收斂，和是 −ln 2）。","收斂區間 [−1, 1)。"],"answer":"[−1, 1)"},{"title":"中心不在 0","prompt":"求 Σ_{n=1}^∞ (x − 2)ⁿ/(n · 3ⁿ) 的收斂區間。","problemId":"lec-14-q1a","steps":["比值 → |x − 2|/3，R = 3，中心 2。端點 2 − 3 = −1 與 2 + 3 = 5。","x = 5：(x − 2)ⁿ/3ⁿ = 1，級數是 Σ 1/n，發散。","x = −1：(x − 2)ⁿ/3ⁿ = (−3)ⁿ/3ⁿ = (−1)ⁿ，級數是 Σ (−1)ⁿ/n，收斂。","收斂區間 [−1, 5)。"],"answer":"[−1, 5)"},{"title":"兩端都發散","prompt":"求 Σ_{n=1}^∞ n(x + 1)ⁿ/4ⁿ 的收斂區間。","problemId":"lec-14-q1b","steps":["比值：((n + 1)/n) · |x + 1|/4 → |x + 1|/4，R = 4，中心 −1。端點 −5 與 3。","x = 3：(x + 1)ⁿ/4ⁿ = 1，級數是 Σ n，各項 → ∞，發散。","x = −5：(x + 1)ⁿ/4ⁿ = (−1)ⁿ，級數是 Σ (−1)ⁿ n，各項大小是 n，不趨近 0，發散。","收斂區間 (−5, 3)。"],"answer":"(−5, 3)"}],"pitfalls":["忘了檢查端點，直接寫開區間。","在端點上用比值判別，得到 1 之後卡住。","(x − 2)ⁿ 的中心讀成 −2，端點全部錯位。","(2x − 1)ⁿ 的半徑沒有除以 2。","端點代入後符號算錯：(−3)ⁿ/3ⁿ = (−1)ⁿ。"],"checks":[{"ask":"Σ xⁿ/n² 的收斂區間是？","options":[{"label":"[−1, 1]","correct":true},{"label":"(−1, 1)","why":"兩個端點都要代：x = ±1 時是 Σ (±1)ⁿ/n²，絕對值是 Σ 1/n²，收斂。"},{"label":"[−1, 1)","why":"x = 1 時是 Σ 1/n²，p = 2 > 1，收斂，不是調和級數。"}]},{"ask":"Σ_{n=0}^∞ xⁿ 的收斂區間是？","options":[{"label":"(−1, 1)","correct":true},{"label":"[−1, 1)","why":"x = −1 時是 1 − 1 + 1 − …，各項不趨近 0，發散。"},{"label":"[−1, 1]","why":"兩個端點的各項都是 ±1，不趨近 0，都發散。"}]},{"ask":"為什麼端點不能用比值判別？","options":[{"label":"在端點上比值的極限剛好是 1，判別法沒有結論","correct":true},{"label":"因為端點上級數一定發散","why":"端點可能收斂，例如 Σ xⁿ/n 在 x = −1。"},{"label":"因為端點上級數一定收斂","why":"也可能發散，例如 Σ xⁿ/n 在 x = 1。"}]},{"ask":"Σ_{n=1}^∞ (2x − 1)ⁿ/√n 的收斂區間是？","options":[{"label":"[0, 1)","correct":true},{"label":"[−1, 1)","why":"(2x − 1)ⁿ = 2ⁿ(x − 1/2)ⁿ，中心 1/2、半徑 1/2；|2x − 1| < 1 給的是 0 < x < 1。"},{"label":"(0, 1]","why":"端點反了：x = 1 時是 Σ 1/√n，發散；x = 0 時是 Σ (−1)ⁿ/√n，收斂。"}]}],"practice":[{"id":"lec-14-m5","core":true},{"id":"lec-14-q1a","core":true},{"id":"lec-14-q1b","core":true},{"id":"lec-14-q1c","core":true},{"id":"gap-ser-end-002"},{"id":"gap-ser-end-001"},{"id":"rel-adv-020"},{"id":"rel-hard-ser-011"},{"id":"lec-14-q4a"},{"id":"lec-14-q1d","challenge":true,"note":"挑戰：(2x − 1)ⁿ 要先改寫成 2ⁿ(x − 1/2)ⁿ，中心和半徑才讀得對。"}]},"power-series-calculus":{"id":"power-series-calculus","prerequisites":["interval-of-convergence","ftc-part1"],"next":["taylor-polynomial"],"related":["limit-derivative-swap","uniform-convergence"],"objectives":["在收斂半徑內逐項微分、逐項積分，並知道半徑不變、端點可能改變。","從 1/(1 − x) 推出 1/(1 − x)²、ln(1 + x)、arctan x 的冪級數。","把數值級數（如 Σ n/2ⁿ、Σ 1/(n·2ⁿ)）看成某個冪級數在特定 x 的值，求出它的和。"],"concept":[{"heading":"① 像多項式一樣逐項處理","body":["若 f(x) = Σ cₙ(x − a)ⁿ 的收斂半徑 R > 0，則在 (a − R, a + R) 內 f 可微，而且可以逐項微分、逐項積分：f′(x) = Σ n cₙ(x − a)ⁿ⁻¹，∫ₐˣ f(t) dt = Σ cₙ(x − a)ⁿ⁺¹/(n + 1)。","兩個新級數的收斂半徑都還是 R。但端點的收斂性可能改變，要重新檢查（〈收斂區間〉）。"],"tex":["f'(x)=\\sum_{n=1}^{\\infty} n\\,c_n (x-a)^{n-1},\\qquad \\int_a^x f(t)\\,dt=\\sum_{n=0}^{\\infty} \\frac{c_n}{n+1}(x-a)^{n+1}"]},{"heading":"② 這件事並不理所當然","body":["有限項的和可以逐項微分，這是微分的線性。無窮多項的和不一定可以：「先取極限再微分」和「先微分再取極限」一般不能交換（〈極限與微分交換〉有反例）。冪級數之所以可以，是因為它在比 R 小的閉區間上一致收斂（〈一致收斂〉）。這裡先接受定理，證明留到分析的支線。"]},{"heading":"③ 從幾何級數出發，造出一整批","body":["1/(1 − x) = Σ xⁿ（|x| < 1）。","微分：1/(1 − x)² = Σ_{n=1}^∞ n xⁿ⁻¹。","1/(1 + t) = Σ (−1)ⁿ tⁿ，從 0 積到 x：ln(1 + x) = Σ_{n=1}^∞ (−1)^{n+1} xⁿ/n。","1/(1 + t²) = Σ (−1)ⁿ t²ⁿ，從 0 積到 x：arctan x = Σ_{n=0}^∞ (−1)ⁿ x^{2n+1}/(2n + 1)。","積分時記得用定積分 ∫₀ˣ，常數就自動定好：ln(1 + 0) = 0、arctan 0 = 0。"]},{"heading":"④ 用它求數值級數的和","body":["看到 Σ n/2ⁿ、Σ 1/(n·3ⁿ) 這種式子，把 1/2 或 1/3 想成 x，找出哪個冪級數長這樣，再代值。代的 x 要在收斂區間內。","端點要小心：ln(1 + x) 的級數在 x = 1 收斂，和確實是 ln 2，但這需要另一個定理（Abel 定理）保證，不能只靠逐項積分。"]}],"workedExamples":[{"title":"逐項微分求和","prompt":"求 Σ_{n=1}^∞ n/2ⁿ。","problemId":"lec-14-q3a","steps":["從 Σ_{n=0}^∞ xⁿ = 1/(1 − x) 逐項微分：Σ_{n=1}^∞ n xⁿ⁻¹ = 1/(1 − x)²，|x| < 1。","兩邊乘 x：Σ n xⁿ = x/(1 − x)²。","x = 1/2 在 (−1, 1) 內：Σ n/2ⁿ = (1/2)/(1/2)² = 2。"],"answer":"2"},{"title":"逐項積分得到 ln","prompt":"寫出 ln(1 + x) 的冪級數，並求 Σ_{n=1}^∞ 1/(n · 2ⁿ)。","problemId":"lec-14-q3c","steps":["1/(1 + t) = Σ (−1)ⁿ tⁿ（|t| < 1）。從 0 積到 x：ln(1 + x) = Σ_{n=0}^∞ (−1)ⁿ xⁿ⁺¹/(n + 1) = x − x²/2 + x³/3 − …。","要的級數全是正號，用 x → −x：ln(1 − x) = −x − x²/2 − x³/3 − …，所以 Σ xⁿ/n = −ln(1 − x)。","x = 1/2：Σ 1/(n · 2ⁿ) = −ln(1/2) = ln 2。"],"answer":"ln(1 + x) = Σ (−1)^{n+1} xⁿ/n；所求為 ln 2"},{"title":"arctan 的級數","prompt":"利用 arctan x 的冪級數，求 Σ_{n=0}^∞ (−1)ⁿ/((2n + 1) 3ⁿ)。","problemId":"lec-14-q3d","steps":["arctan x = Σ (−1)ⁿ x^{2n+1}/(2n + 1)，|x| < 1（由 1/(1 + t²) 逐項積分）。","要湊出 3ⁿ：取 x = 1/√3，x^{2n+1} = (1/3)ⁿ · (1/√3)。所以 arctan(1/√3) = (1/√3) Σ (−1)ⁿ/((2n + 1)3ⁿ)。","arctan(1/√3) = π/6，所求 = √3 · π/6 = π/(2√3)。"],"answer":"π/(2√3)"}],"pitfalls":["逐項積分時只把次方加一，忘了除以 n + 1。","不定積分忘了常數；用 ∫₀ˣ 就不會漏。","代入的 x 落在收斂區間外。","以為逐項微分、積分後端點的收斂性不變。","Σ n xⁿ 和 Σ n xⁿ⁻¹ 搞混，少乘或多乘一個 x。"],"checks":[{"ask":"Σ_{n=0}^∞ xⁿ 逐項積分（從 0 到 x）得到？","options":[{"label":"Σ xⁿ⁺¹/(n + 1)","correct":true},{"label":"Σ n xⁿ⁻¹","why":"那是逐項微分。積分要把次方加一、再除以新的次方。"},{"label":"Σ xⁿ⁺¹","why":"次方加一之後還要除以 n + 1；∫ tⁿ dt = tⁿ⁺¹/(n + 1)。"}]},{"ask":"冪級數逐項微分後，收斂半徑會？","options":[{"label":"不變","correct":true},{"label":"變大","why":"係數多乘了 n，比值 (n + 1)/n → 1，半徑不受影響。"},{"label":"可能變成 0","why":"多乘一個多項式因子不改變 R；改變的只可能是端點。"}]},{"ask":"Σ_{n=1}^∞ n/3ⁿ = ？","options":[{"label":"3/4","correct":true},{"label":"9/4","why":"這是 Σ n xⁿ⁻¹ = 1/(1 − x)² 在 x = 1/3 的值；Σ n xⁿ 還要再乘一個 x。"},{"label":"1/2","why":"這是 Σ_{n=1}^∞ (1/3)ⁿ；忘了係數 n，要用微分過的級數。"}]},{"ask":"1/(1 + x) 的級數在 x = 1 發散，積分得到的 ln(1 + x) 級數在 x = 1 呢？","options":[{"label":"收斂（是交錯調和級數）","correct":true},{"label":"一定也發散，因為積分不改變收斂性","why":"積分不改變半徑，但端點可以改變：1 − 1/2 + 1/3 − … 收斂。"},{"label":"沒有意義，x = 1 不在定義域","why":"ln(1 + x) 在 x = 1 好好的；級數在那裡也收斂。"}]}],"practice":[{"id":"lec-14-q3a","core":true},{"id":"cx-smid-008","core":true},{"id":"lec-14-q2b","core":true},{"id":"lec-14-q2c","core":true},{"id":"lec-14-q3c","core":true},{"id":"exam-ser-020"},{"id":"fd-serx-204"},{"id":"world-009"},{"id":"depth-ser-011"},{"id":"lec-14-q3b"},{"id":"lec-14-q3d"},{"id":"fd-serb-605"},{"id":"fd-serx-406","challenge":true,"note":"挑戰：先部分分式 1/(n(n + 1)) = 1/n − 1/(n + 1)，兩邊各是一個 −ln(1 − x) 型的級數。"}]},"taylor-polynomial":{"id":"taylor-polynomial","prerequisites":["linear-approximation","higher-derivatives"],"next":["taylor-series"],"related":["power-series","maclaurin-series","taylor-error"],"objectives":["說出 Taylor 多項式的想法：在 a 點與 f 有相同的值、一階、二階……到 n 階導數。","推出並使用係數公式 f⁽ᵏ⁾(a)/k!。","寫出中心不在 0 的 Taylor 多項式，並用它估計函數值。"],"concept":[{"heading":"① 從切線再往前一步","body":["〈線性近似〉用切線 f(a) + f′(a)(x − a) 近似 f：它跟 f 在 a 點的值一樣、斜率一樣。但切線不會彎，離 a 遠一點就差很多。","想法：用二次多項式，讓它在 a 點的值、斜率、彎曲程度（二階導數）都跟 f 一樣；再不夠，就用三次、四次……。對準的導數越多，貼合得越好。"]},{"heading":"② 係數怎麼來","body":["設 T(x) = c₀ + c₁(x − a) + c₂(x − a)² + … + cₙ(x − a)ⁿ。把它微分 k 次再代 x = a：比 k 次低的項都微成 0，比 k 次高的項代 a 都是 0，只剩 (x − a)ᵏ 那項微分 k 次得 k! · cₖ。","要 T⁽ᵏ⁾(a) = f⁽ᵏ⁾(a)，就得 k! · cₖ = f⁽ᵏ⁾(a)，也就是 cₖ = f⁽ᵏ⁾(a)/k!。這樣得到的多項式叫 n 階 Taylor 多項式："],"tex":["T_n(x)=\\sum_{k=0}^{n}\\frac{f^{(k)}(a)}{k!}(x-a)^k=f(a)+f'(a)(x-a)+\\frac{f''(a)}{2!}(x-a)^2+\\cdots"]},{"heading":"③ 幾個要點","body":["T₁ 就是切線。中心 a = 0 時特別常用，叫 Maclaurin 多項式（〈Maclaurin 級數〉）。","係數是常數：先求出 f⁽ᵏ⁾(x)，再代 a。","n 階 Taylor 多項式的次數最多是 n；某些導數在 a 是 0 時，那一項就不見了（例如 cos x 只有偶次項）。","它在 a 附近很準，但離 a 越遠通常越差。準到什麼程度，要等〈Taylor 誤差〉。"]}],"workedExamples":[{"title":"eˣ 在 0","prompt":"求 eˣ 在 x = 0 的三階 Taylor 多項式 T₃，並計算 T₃(1)。","problemId":"tr-val-001","steps":["eˣ 的每一階導數都是 eˣ，在 0 的值都是 1。","T₃(x) = 1 + x + x²/2! + x³/3! = 1 + x + x²/2 + x³/6。","T₃(1) = 1 + 1 + 1/2 + 1/6 = 8/3 ≈ 2.667，而 e ≈ 2.718。"],"answer":"T₃(1) = 8/3"},{"title":"中心不在 0","prompt":"求 f(x) = √x 在 a = 4 的二階 Taylor 多項式，並估計 √4.1。","problemId":"lec-15-q1b","steps":["f(4) = 2。f′(x) = 1/(2√x)，f′(4) = 1/4。f″(x) = −1/(4x^{3/2})，f″(4) = −1/(4 · 8) = −1/32。","T₂(x) = 2 + (1/4)(x − 4) + (−1/32)/2! · (x − 4)² = 2 + (x − 4)/4 − (x − 4)²/64。","x = 4.1，x − 4 = 0.1：T₂ = 2 + 0.025 − 0.01/64 = 2.02484375。","真正的 √4.1 ≈ 2.0248457，只差約 2 × 10⁻⁶。"],"answer":"T₂(4.1) = 2.02484375"},{"title":"只有偶次項","prompt":"求 cos x 在 0 的四階 Taylor 多項式，並計算 T₄(1/2)。","problemId":"tr-val-003","steps":["導數循環：cos、−sin、−cos、sin、cos。在 0 的值：1、0、−1、0、1。","T₄(x) = 1 + 0 · x − x²/2! + 0 · x³ + x⁴/4! = 1 − x²/2 + x⁴/24。","T₄(1/2) = 1 − 1/8 + 1/384 = 337/384 ≈ 0.87760，cos(1/2) ≈ 0.87758。"],"answer":"337/384"}],"pitfalls":["係數忘了除以 k!。","係數寫成 f⁽ᵏ⁾(x)，沒有代 a。","中心是 a 卻寫成 xᵏ 而不是 (x − a)ᵏ。","漏了常數項 f(a)。"],"figures":[{"caption":"階數越高，貼住 cos x 的範圍越寬","after":0,"widget":{"type":"taylor","f":"cos(x)","center":0,"coeffs":["1","0","-1/2","0","1/24","0","-1/720","0","1/40320","0","-1/3628800"],"order":[0,10],"value":2,"window":[-7,7,-2.5,2.5]}}],"checks":[{"ask":"Tₙ(x) 裡 (x − a)ᵏ 的係數是？","options":[{"label":"f⁽ᵏ⁾(a)/k!","correct":true},{"label":"f⁽ᵏ⁾(a)","why":"(x − a)ᵏ 微分 k 次會冒出 k!，要除掉它，T⁽ᵏ⁾(a) 才會等於 f⁽ᵏ⁾(a)。"},{"label":"f⁽ᵏ⁾(x)/k!","why":"係數要是常數；f⁽ᵏ⁾ 要在中心 a 取值。"}]},{"ask":"eˣ 在 0 的二階 Taylor 多項式是？","options":[{"label":"1 + x + x²/2","correct":true},{"label":"1 + x + x²","why":"二次項要除以 2! = 2。"},{"label":"x + x²/2","why":"漏了常數項 f(0) = e⁰ = 1。"}]},{"ask":"一階 Taylor 多項式 T₁ 是？","options":[{"label":"f 在 a 的切線","correct":true},{"label":"通過 (a, f(a)) 與 (b, f(b)) 的割線","why":"T₁ 只用 a 點的資訊：值與導數；它就是切線 f(a) + f′(a)(x − a)。"},{"label":"常數 f(a)","why":"那是 T₀；T₁ 多了一次項 f′(a)(x − a)。"}]},{"ask":"sin x 在 0 的三階 Taylor 多項式是？","options":[{"label":"x − x³/6","correct":true},{"label":"x − x³/3","why":"三次項的係數是 f‴(0)/3! = −1/6，不是除以 3。"},{"label":"1 − x²/2","why":"這是 cos x 的二階多項式；sin 0 = 0，所以沒有常數項。"}]}],"practice":[{"id":"tr-val-001","core":true},{"id":"tr-val-002","core":true},{"id":"lec-15-m4","core":true},{"id":"lec-15-q1a","core":true},{"id":"lec-15-q1b","core":true},{"id":"tr-val-003"},{"id":"tr-val-004"},{"id":"tr-val-005"},{"id":"lec-15-m1"},{"id":"gap-ser-taylor-002"},{"id":"tr-val-007","challenge":true,"note":"挑戰：e^{−x²} 直接微分很累；先把 eᵘ 的多項式中的 u 換成 −x²，再只留到四次。"}]},"taylor-series":{"id":"taylor-series","prerequisites":["taylor-polynomial","power-series-calculus"],"next":["maclaurin-series"],"related":["taylor-error","radius-of-convergence"],"objectives":["寫出 f 在 a 的 Taylor 級數 Σ f⁽ⁿ⁾(a)(x − a)ⁿ/n!，並求它的收斂半徑。","使用唯一性：任何方法得到的冪級數表示，就是 Taylor 級數；反過來可以從係數讀出高階導數。","知道 Taylor 級數收斂不代表等於 f：要餘項 Rₙ(x) → 0。"],"concept":[{"heading":"① 讓 n → ∞","body":["f 在 a 有任意階導數時，把〈Taylor 多項式〉一路寫下去，得到一個冪級數，叫 f 在 a 的 Taylor 級數。它有自己的收斂半徑，用〈收斂半徑〉的方法求。"],"tex":["\\sum_{n=0}^{\\infty}\\frac{f^{(n)}(a)}{n!}(x-a)^n"]},{"heading":"② 唯一性：不必真的去微分","body":["若在 a 附近 f(x) = Σ cₙ(x − a)ⁿ（R > 0），把兩邊逐項微分 n 次再代 x = a，得 f⁽ⁿ⁾(a) = n! cₙ，也就是 cₙ = f⁽ⁿ⁾(a)/n!。所以 f 的冪級數表示只有一種，就是 Taylor 級數。","實用上有兩個方向：一、用幾何級數、代換、逐項積分這些捷徑得到的級數，就是 Taylor 級數，不必算一堆導數；二、知道級數就能讀出導數：f⁽ⁿ⁾(a) = n! × (第 n 項係數)。"]},{"heading":"③ 收斂了，不一定等於 f","body":["Taylor 級數是用 f 在 a「一個點」的導數造出來的，它不保證在別的地方等於 f。經典例子：f(x) = e^{−1/x²}（x ≠ 0），f(0) = 0。可以證明 f 在 0 的每一階導數都是 0，所以它的 Taylor 級數是 0 + 0 + …，處處收斂到 0，但 x ≠ 0 時 f(x) > 0。","f(x) 等於它的 Taylor 級數，條件是餘項 Rₙ(x) = f(x) − Tₙ(x) → 0。怎麼估計 Rₙ，是〈Taylor 誤差〉的主題。常見的 eˣ、sin x、cos x 都能證明 Rₙ → 0，所以在整條實數線上等於自己的 Taylor 級數。"]}],"workedExamples":[{"title":"ln x 在 a = 1","prompt":"求 ln x 在 a = 1 的 Taylor 級數與收斂半徑。","steps":["f′(x) = 1/x，f″(x) = −1/x²，f‴(x) = 2/x³，一般 f⁽ⁿ⁾(x) = (−1)^{n−1}(n − 1)!/xⁿ（n ≥ 1）。f(1) = 0。","係數 f⁽ⁿ⁾(1)/n! = (−1)^{n−1}(n − 1)!/n! = (−1)^{n−1}/n。","Taylor 級數：Σ_{n=1}^∞ (−1)^{n−1}(x − 1)ⁿ/n = (x − 1) − (x − 1)²/2 + (x − 1)³/3 − …。","比值 → |x − 1|，R = 1。"],"answer":"Σ (−1)^{n−1}(x − 1)ⁿ/n，R = 1"},{"title":"用幾何級數代替微分","prompt":"求 1/x 在 a = 2 的 Taylor 級數。","steps":["湊出 1/(1 − u)：1/x = 1/(2 + (x − 2)) = (1/2) · 1/(1 + (x − 2)/2)。","= (1/2) Σ (−(x − 2)/2)ⁿ = Σ (−1)ⁿ (x − 2)ⁿ/2ⁿ⁺¹，條件 |x − 2| < 2。","由唯一性，這就是 Taylor 級數。順便讀出 f′(2) = 1! × (−1/4) = −1/4，跟直接微分 −1/x² 在 2 的值一致。"],"answer":"Σ (−1)ⁿ (x − 2)ⁿ/2ⁿ⁺¹，|x − 2| < 2"},{"title":"從係數讀出高階導數","prompt":"f(x) = x²eˣ，求 f⁽¹⁰⁾(0)。","problemId":"lec-15-m2","steps":["eˣ = Σ xⁿ/n!，所以 x²eˣ = Σ xⁿ⁺²/n!。","x¹⁰ 的係數來自 n = 8：1/8!。","由 f⁽¹⁰⁾(0) = 10! × (x¹⁰ 的係數) = 10!/8! = 10 × 9 = 90。直接微分十次要用十次乘法法則。"],"answer":"90"}],"pitfalls":["從係數讀導數時忘了乘 n!。","以為 Taylor 級數收斂，就一定收斂到 f。","用代換得到級數之後，又多此一舉地重新微分驗證。","中心是 a 時，收斂範圍寫成以 0 為中心。"],"checks":[{"ask":"在 0 附近 f(x) = Σ cₙxⁿ。c₃ 等於？","options":[{"label":"f‴(0)/6","correct":true},{"label":"f‴(0)","why":"x³ 微分三次得 3! = 6，所以 f‴(0) = 6c₃。"},{"label":"f‴(0)/3","why":"要除的是 3! = 6，不是 3。"}]},{"ask":"e^{−1/x²}（補 f(0) = 0）的例子說明了什麼？","options":[{"label":"Taylor 級數可能收斂，卻不等於原函數","correct":true},{"label":"Taylor 級數一定發散","why":"它的 Taylor 級數每一項都是 0，處處收斂（到 0）；問題是 0 ≠ f(x)。"},{"label":"每個無窮可微的函數都等於它的 Taylor 級數","why":"這正是被它推翻的說法：它無窮可微，卻不等於自己的 Taylor 級數。"}]},{"ask":"f(x) = Σ_{n=0}^∞ (n + 1)xⁿ。f″(0) = ？","options":[{"label":"6","correct":true},{"label":"3","why":"3 是 x² 的係數；導數要再乘 2! = 2。"},{"label":"2","why":"2 是 x¹ 的係數，也是 f′(0)；f″(0) = 2! × 3 = 6。"}]},{"ask":"要證明 f 在某區間等於它的 Taylor 級數，需要的是？","options":[{"label":"餘項 Rₙ(x) = f(x) − Tₙ(x) → 0","correct":true},{"label":"Taylor 級數在那裡收斂","why":"收斂不夠：可能收斂到別的函數，例如 e^{−1/x²} 的 Taylor 級數收斂到 0。"},{"label":"f 無窮可微","why":"e^{−1/x²} 無窮可微，卻不等於自己的 Taylor 級數。"}]}],"practice":[{"id":"lec-15-m2","core":true},{"id":"lec-14-q2b","core":true},{"id":"lec-14-q2c","core":true},{"id":"ser-027"},{"id":"world-068","challenge":true,"note":"挑戰：(1 + x)ˣ = e^{x ln(1 + x)}，先展開指數上的 x ln(1 + x)，再代進 eᵘ 的級數。"}]},"maclaurin-series":{"id":"maclaurin-series","prerequisites":["taylor-series"],"next":["binomial-series"],"related":["geometric-series","power-series-calculus","taylor-error"],"objectives":["背熟五個基本 Maclaurin 級數與它們成立的範圍：eˣ、sin x、cos x、ln(1 + x)、1/(1 − x)。","用代換、乘 xᵏ、逐項微分積分、兩個級數相乘，造出新級數並讀出係數。","認出數值級數是哪個基本級數在某一點的值。"],"concept":[{"heading":"① 五個要背的","body":["Maclaurin 級數就是中心 a = 0 的 Taylor 級數。下面五個是所有計算的起點："],"tex":["e^x=\\sum_{n=0}^{\\infty}\\frac{x^n}{n!}=1+x+\\frac{x^2}{2!}+\\frac{x^3}{3!}+\\cdots\\qquad(\\text{所有 } x)","\\sin x=\\sum_{n=0}^{\\infty}\\frac{(-1)^n x^{2n+1}}{(2n+1)!}=x-\\frac{x^3}{3!}+\\frac{x^5}{5!}-\\cdots\\qquad(\\text{所有 } x)","\\cos x=\\sum_{n=0}^{\\infty}\\frac{(-1)^n x^{2n}}{(2n)!}=1-\\frac{x^2}{2!}+\\frac{x^4}{4!}-\\cdots\\qquad(\\text{所有 } x)","\\ln(1+x)=\\sum_{n=1}^{\\infty}\\frac{(-1)^{n+1}x^n}{n}=x-\\frac{x^2}{2}+\\frac{x^3}{3}-\\cdots\\qquad(-1<x\\le 1)","\\frac{1}{1-x}=\\sum_{n=0}^{\\infty}x^n=1+x+x^2+\\cdots\\qquad(-1<x<1)"]},{"heading":"② 它們從哪裡來","body":["eˣ：每一階導數都是 eˣ，在 0 都是 1，係數 1/n!。","sin x：導數在 0 依序是 0, 1, 0, −1 循環，所以只有奇次項、正負交替。cos x 是 sin x 逐項微分的結果，只有偶次項。","1/(1 − x)：〈幾何級數〉。ln(1 + x)：把 1/(1 + t) 逐項積分（〈冪級數的微分與積分〉）。","前三個在所有 x 都等於原函數，這需要證明餘項 → 0，在〈Taylor 誤差〉完成。"]},{"heading":"③ 造新級數的四招","body":["代換：x 換成 x²、−x、2x……，範圍跟著換。例如 e^{−x²} = Σ (−1)ⁿx²ⁿ/n!。","乘 xᵏ：每一項次方加 k。","逐項微分、積分。","兩個級數相乘：只展開到需要的次方。求 x³ 的係數，就只收集次方加起來是 3 的乘積。","這些捷徑得到的都是真正的 Maclaurin 級數（〈Taylor 級數〉的唯一性），不必再微分驗證。"]}],"workedExamples":[{"title":"代換","prompt":"求 sin(x²) 的 Maclaurin 級數中 x⁶ 與 x¹⁰ 的係數。","problemId":"rel-hard-ser-004","steps":["sin u = u − u³/3! + u⁵/5! − …，u = x²。","sin(x²) = x² − x⁶/6 + x¹⁰/120 − …。","x⁶ 的係數 −1/6，x¹⁰ 的係數 1/120。（x⁸ 的係數是 0：只有 4k + 2 次方的項。）"],"answer":"−1/6 與 1/120"},{"title":"兩個級數相乘","prompt":"求 eˣ ln(1 + x) 的 x³ 係數。","problemId":"depth-ser-015","steps":["eˣ = 1 + x + x²/2 + …，ln(1 + x) = x − x²/2 + x³/3 − …。","收集次方和為 3 的乘積：1 · (x³/3) + x · (−x²/2) + (x²/2) · x。","係數 = 1/3 − 1/2 + 1/2 = 1/3。"],"answer":"1/3"},{"title":"認出是哪個級數","prompt":"求 Σ_{n=0}^∞ (−1)ⁿ π^{2n+1}/(6^{2n+1}(2n + 1)!)。","problemId":"lec-15-q3c","steps":["π^{2n+1}/6^{2n+1} = (π/6)^{2n+1}，所以這是 Σ (−1)ⁿ (π/6)^{2n+1}/(2n + 1)!。","正是 sin x 的級數在 x = π/6 的值。","和 = sin(π/6) = 1/2。（只取到 x⁷ 項：π/6 − (π/6)³/6 + (π/6)⁵/120 − (π/6)⁷/5040 ≈ 0.5000000，已經非常準。）"],"answer":"1/2"}],"pitfalls":["sin、cos 的奇偶次方或正負號記反。","代換 2x 時只換了 x，沒把係數一起 n 次方：(2x)ⁿ = 2ⁿxⁿ。","ln(1 + x) 的級數從 n = 0 開始，或以為它在所有 x 都成立。","相乘時漏掉某一組次方和相同的乘積。"],"checks":[{"ask":"cos x 的 Maclaurin 級數是？","options":[{"label":"Σ (−1)ⁿ x²ⁿ/(2n)!","correct":true},{"label":"Σ (−1)ⁿ x^{2n+1}/(2n + 1)!","why":"這是 sin x：cos 0 = 1，常數項不是 0，所以是偶次方。"},{"label":"Σ x²ⁿ/(2n)!","why":"少了正負交替；cos x 的二階導數在 0 是 −1，所以 x² 的係數是 −1/2。"}]},{"ask":"ln(1 + x) 的 Maclaurin 級數在哪裡成立？","options":[{"label":"−1 < x ≤ 1","correct":true},{"label":"−1 < x < 1","why":"x = 1 時是交錯調和級數 1 − 1/2 + 1/3 − …，收斂到 ln 2。"},{"label":"所有實數","why":"收斂半徑是 1；|x| > 1 時各項 xⁿ/n 不趨近 0。"}]},{"ask":"e^{2x} 的 Maclaurin 級數中，x⁴ 的係數是？","options":[{"label":"2/3","correct":true},{"label":"1/24","why":"代換 2x 時要整個 4 次方：(2x)⁴/4! = 16x⁴/24。"},{"label":"16","why":"忘了除以 4! = 24。"}]},{"ask":"Σ_{n=0}^∞ 3ⁿ/n! = ？","options":[{"label":"e³","correct":true},{"label":"3e","why":"3ⁿ/n! 是 xⁿ/n! 在 x = 3 的值，和是 e³，不是 e 乘 3。"},{"label":"發散","why":"比值 3/(n + 1) → 0，收斂；這正是 eˣ 的級數。"}]}],"practice":[{"id":"lec-15-m1","core":true},{"id":"ser-038","core":true},{"id":"ser-027","core":true},{"id":"rel-adv-017","core":true},{"id":"exam-ser-017","core":true},{"id":"uni-ser-006","core":true},{"id":"uni-ser-004"},{"id":"depth-ser-005"},{"id":"depth-ser-013"},{"id":"depth-ser-018"},{"id":"lec-15-q3c"},{"id":"lec-15-q3d"},{"id":"depth-ser-015"},{"id":"lec-14-q4d"},{"id":"uni-ser-016","challenge":true,"note":"挑戰：sin x cos x = ½ sin 2x，先用恆等式比直接相乘快得多。"},{"id":"depth-ser-019","challenge":true}]},"binomial-series":{"id":"binomial-series","prerequisites":["maclaurin-series"],"next":["taylor-error"],"related":["geometric-series","linear-approximation"],"objectives":["會算廣義二項係數 C(k, n) = k(k − 1)⋯(k − n + 1)/n!，k 可以是負數或分數。","寫出 (1 + x)ᵏ = Σ C(k, n) xⁿ（|x| < 1），並知道 k 是非負整數時它退化成有限的二項式定理。","用它展開 √(1 + x)、1/√(1 + x)、1/(1 − x)³，讀出係數或做近似。"],"concept":[{"heading":"① 從二項式定理出發","body":["k 是正整數時，(1 + x)ᵏ = Σ_{n=0}^{k} C(k, n) xⁿ，是有限和。把 C(k, n) 寫成 k(k − 1)⋯(k − n + 1)/n!，這個寫法對任何實數 k 都有意義，叫廣義二項係數；規定 C(k, 0) = 1。","例：C(1/2, 2) = (1/2)(−1/2)/2! = −1/8；C(−1, n) = (−1)(−2)⋯(−n)/n! = (−1)ⁿ。"]},{"heading":"② 二項級數","body":["f(x) = (1 + x)ᵏ 的 n 階導數是 k(k − 1)⋯(k − n + 1)(1 + x)^{k−n}，在 0 的值除以 n! 正好是 C(k, n)。所以它的 Maclaurin 級數是 (1 + x)ᵏ = Σ C(k, n) xⁿ = 1 + kx + k(k − 1)x²/2! + …。","k 不是非負整數時，係數永遠不會變 0，比值 |C(k, n + 1)/C(k, n)| = |k − n|/(n + 1) → 1，收斂半徑是 1。可以證明在 |x| < 1 內級數確實等於 (1 + x)ᵏ。端點的情況隨 k 而不同，這裡不討論。","k 是非負整數時，n > k 的係數都含有因子 (k − k) = 0，級數變成有限多項式，對所有 x 成立，就是原本的二項式定理。"],"tex":["(1+x)^k=\\sum_{n=0}^{\\infty}\\binom{k}{n}x^n=1+kx+\\frac{k(k-1)}{2!}x^2+\\frac{k(k-1)(k-2)}{3!}x^3+\\cdots\\qquad(\\lvert x\\rvert<1)"]},{"heading":"③ 幾個常用的","body":["k = −1：1/(1 + x) = 1 − x + x² − …，跟〈幾何級數〉一致。","k = 1/2：√(1 + x) = 1 + x/2 − x²/8 + x³/16 − …。前兩項就是〈線性近似〉的 √(1 + x) ≈ 1 + x/2。","k = −1/2：1/√(1 + x) = 1 − x/2 + 3x²/8 − 5x³/16 + …。","(1 − x)ᵏ 就把 x 換成 −x；(a + x)ᵏ 先提出 aᵏ：(a + x)ᵏ = aᵏ(1 + x/a)ᵏ，條件變成 |x| < |a|。"]}],"workedExamples":[{"title":"√(1 + x) 與近似","prompt":"寫出 √(1 + x) 的二項級數到 x³，並估計 √1.1。","problemId":"lec-15-m4","steps":["k = 1/2。C(1/2, 1) = 1/2；C(1/2, 2) = (1/2)(−1/2)/2 = −1/8；C(1/2, 3) = (1/2)(−1/2)(−3/2)/6 = 1/16。","√(1 + x) = 1 + x/2 − x²/8 + x³/16 − …。","x = 0.1：1 + 0.05 − 0.00125 + 0.0000625 = 1.0488125。真正的 √1.1 ≈ 1.0488088，差約 4 × 10⁻⁶。"],"answer":"1 + x/2 − x²/8 + x³/16；√1.1 ≈ 1.0488125"},{"title":"負分數次方","prompt":"求 (1 + x)^{−1/2} 的 Maclaurin 級數中 x³ 的係數。","problemId":"lec-15-q4a","steps":["C(−1/2, 3) = (−1/2)(−3/2)(−5/2)/3!。","分子 = −15/8，除以 6：−15/48 = −5/16。"],"answer":"−5/16"},{"title":"負整數次方","prompt":"求 1/(1 − x)³ 的 Maclaurin 級數中 x⁴ 的係數。","problemId":"uni-ser-013","steps":["1/(1 − x)³ = (1 + (−x))^{−3}，k = −3，x 換成 −x。","x⁴ 的係數 = C(−3, 4) · (−1)⁴ = (−3)(−4)(−5)(−6)/4! = 360/24 = 15。","檢查：一般項是 C(n + 2, 2)xⁿ，前幾個係數 1, 3, 6, 10, 15，n = 4 時是 15。"],"answer":"15"}],"pitfalls":["C(k, n) 忘了除以 n!。","分數次方的連乘，負號數錯：(1/2)(−1/2)(−3/2) 有兩個負號，是正的。","(1 − x)ᵏ 換成 −x 之後，忘了 (−x)ⁿ 的符號。","以為二項級數對所有 x 都成立；k 不是非負整數時只在 |x| < 1。"],"checks":[{"ask":"C(1/2, 2) = ？","options":[{"label":"−1/8","correct":true},{"label":"1/8","why":"(1/2)(1/2 − 1) = (1/2)(−1/2) = −1/4，有一個負號。"},{"label":"−1/4","why":"還要除以 2! = 2。"}]},{"ask":"(1 + x)⁵ 用二項級數展開，結果是？","options":[{"label":"有限多項式，對所有 x 成立","correct":true},{"label":"無窮級數，只在 |x| < 1 成立","why":"k = 5 是非負整數，n > 5 的係數都含有因子 0，級數在第 5 次就停了。"},{"label":"無窮級數，對所有 x 成立","why":"根本沒有無窮多項：C(5, n) 在 n ≥ 6 全是 0。"}]},{"ask":"用二項級數展開 1/(1 − x) = (1 − x)^{−1}，得到？","options":[{"label":"Σ xⁿ","correct":true},{"label":"Σ (−1)ⁿ xⁿ","why":"那是 1/(1 + x)。C(−1, n) = (−1)ⁿ，再乘 (−x)ⁿ 的 (−1)ⁿ，兩個負號抵銷。"},{"label":"Σ n xⁿ","why":"C(−1, n) 的大小是 1，不是 n；Σ n xⁿ⁻¹ 是 1/(1 − x)²。"}]},{"ask":"用前兩項估計 √1.02，得到？","options":[{"label":"1.01","correct":true},{"label":"1.02","why":"一次項的係數是 C(1/2, 1) = 1/2，不是 1：1 + 0.02/2。"},{"label":"1.001","why":"x = 0.02，x/2 = 0.01，不是 0.001。"}]}],"practice":[{"id":"lec-15-m4","core":true},{"id":"lec-15-q4a","core":true},{"id":"uni-ser-013","core":true},{"id":"tr-val-005","core":true},{"id":"uni-ser-018"},{"id":"depth-ser-011"},{"id":"lec-15-q4c"},{"id":"world-048","challenge":true,"note":"挑戰：把 (1 − t²)^{−1/2} 用二項級數展開再逐項積分，得到 arcsin x 的級數，最後代 x = 1。"}]},"taylor-error":{"id":"taylor-error","prerequisites":["taylor-polynomial","mean-value-theorem"],"next":["taylor-limits"],"related":["rolle-theorem","alternating-series-test","taylor-series","sequence-limit"],"objectives":["寫出 Lagrange 餘項 Rₙ(x) = f⁽ⁿ⁺¹⁾(c)(x − a)ⁿ⁺¹/(n + 1)!，知道 c 在 a 與 x 之間、但不知道確切位置。","用 Taylor 不等式 |Rₙ(x)| ≤ M|x − a|ⁿ⁺¹/(n + 1)! 估計誤差，並正確選 M。","反過來求「要幾階才夠準」，以及用 Rₙ → 0 證明 eˣ 等於自己的級數。"],"concept":[{"heading":"① 誤差長什麼樣子","body":["Rₙ(x) = f(x) − Tₙ(x)。Taylor 定理（Lagrange 形式）：若 f 在 a 與 x 之間有 n + 1 階導數，則存在某個 c 介於 a 與 x 之間，使 Rₙ(x) = f⁽ⁿ⁺¹⁾(c)(x − a)ⁿ⁺¹/(n + 1)!。","它長得就像 Taylor 多項式的「下一項」，只是導數不是在 a 取值，而是在某個不知道確切位置的 c。n = 0 時這就是〈均值定理〉：f(x) − f(a) = f′(c)(x − a)。"],"tex":["R_n(x)=\\frac{f^{(n+1)}(c)}{(n+1)!}(x-a)^{n+1}"]},{"heading":"② Taylor 不等式：把 c 換成最壞情況","body":["不知道 c 在哪，就用最壞的情況：若在 a 與 x 之間 |f⁽ⁿ⁺¹⁾| ≤ M，則 |Rₙ(x)| ≤ M|x − a|ⁿ⁺¹/(n + 1)!。","M 要涵蓋整段區間，不能只看中心 a。M 不必是最小的上界，取一個好算的也可以（例如 |sin| ≤ 1、e^c < 3），代價是估計比較鬆。","這是「保證不會更差」的上界，不是誤差本身；實際誤差通常小一些。"],"tex":["\\lvert R_n(x)\\rvert\\le \\frac{M\\,\\lvert x-a\\rvert^{n+1}}{(n+1)!}"]},{"heading":"③ 兩個常用的小技巧","body":["sin x 的 T₃ 和 T₄ 是同一個多項式（x⁴ 的係數是 0），所以可以把它當 T₄，用五階導數估誤差，得到更緊的上界（範例 3）。","如果代入後的級數是交錯的、各項遞減到 0，也可以直接用〈交錯級數判別〉的誤差：不超過第一個沒取的項。"]},{"heading":"④ 為什麼 eˣ 等於自己的級數","body":["固定 x。eˣ 的 n + 1 階導數是 eᶜ，c 在 0 與 x 之間，所以 |eᶜ| ≤ e^{|x|}。|Rₙ(x)| ≤ e^{|x|} |x|ⁿ⁺¹/(n + 1)!。階乘長得比任何 |x|ⁿ 快（〈數列與數列極限〉），所以 Rₙ(x) → 0，eˣ 在每一個 x 都等於它的 Maclaurin 級數。sin、cos 同理，M 取 1。"]},{"heading":"⑤ Lagrange 餘項的證明","body":["固定 x ≠ a。對 t 定義 g(t) = f(x) − Σ_{k=0}^{n} f⁽ᵏ⁾(t)(x − t)ᵏ/k! − K(x − t)ⁿ⁺¹，選常數 K 使 g(a) = 0；而 g(x) = f(x) − f(x) = 0 自動成立。由〈Rolle 定理〉，a 與 x 之間有 c 使 g′(c) = 0。","對 t 微分時，Σ 那一串相鄰兩項會互相抵銷，只剩 g′(t) = −f⁽ⁿ⁺¹⁾(t)(x − t)ⁿ/n! + K(n + 1)(x − t)ⁿ。g′(c) = 0 且 x − c ≠ 0，得 K = f⁽ⁿ⁺¹⁾(c)/(n + 1)!。再由 g(a) = 0，Rₙ(x) = f(x) − Tₙ(x) = K(x − a)ⁿ⁺¹，就是所要的式子。"],"collapsible":true}],"workedExamples":[{"title":"要幾階才夠準","prompt":"用 eˣ 的 n 次 Maclaurin 多項式 Tₙ(1) 近似 e。已知 e < 3，用 |Rₙ(1)| ≤ 3/(n + 1)! 求誤差小於 10⁻³ 的最小 n。","problemId":"lec-15-q4d","steps":["M：n + 1 階導數是 eᶜ，0 < c < 1，eᶜ < e < 3，所以 |Rₙ(1)| ≤ 3 · 1ⁿ⁺¹/(n + 1)!。","要 3/(n + 1)! < 0.001，即 (n + 1)! > 3000。6! = 720 不夠，7! = 5040 夠。","n + 1 = 7，n = 6。實際誤差 e − T₆(1) ≈ 0.00023，確實小於上界 3/5040 ≈ 0.0006。"],"answer":"n = 6"},{"title":"M 取區間上的最大值","prompt":"用 √x 在 a = 4 的二次 Taylor 多項式估計 √4.1，M 取 |f‴| 在 [4, 4.1] 的最大值，求誤差上界。","problemId":"lec-15-q1c","steps":["f‴(x) = (3/8)x^{−5/2}，在 [4, 4.1] 上遞減，最大值在 x = 4：(3/8)/32 = 3/256。","|R₂(4.1)| ≤ (3/256)(0.1)³/3! = 1/512000 ≈ 1.95 × 10⁻⁶。","對照〈Taylor 多項式〉的估計值 2.02484375：實際誤差約 1.92 × 10⁻⁶，在上界之內。"],"answer":"1/512000"},{"title":"多用一階，上界更緊","prompt":"用 x − x³/6 近似 sin 1，估計誤差。","steps":["當成 T₃：f⁽⁴⁾ = sin，在 [0, 1] 上最大是 sin 1，上界 sin 1/4! ≈ 0.035。","當成 T₄（x⁴ 的係數是 0，T₃ = T₄）：f⁽⁵⁾ = cos，|cos| ≤ 1，上界 1/5! = 1/120 ≈ 0.0083。","實際誤差 sin 1 − 5/6 ≈ 0.0081，第二個上界緊得多。"],"answer":"誤差 ≤ 1/120"}],"pitfalls":["階數差一：Tₙ 的誤差用的是第 n + 1 階導數、除以 (n + 1)!。","M 只在中心 a 取值，沒有涵蓋到 x 的整段區間。","把上界當成實際誤差。","求「最小 n」時用了 ≤ 而題目要 <，或只試了一個 n 就停。"],"checks":[{"ask":"Tₙ 的 Lagrange 餘項是？","options":[{"label":"f⁽ⁿ⁺¹⁾(c)(x − a)ⁿ⁺¹/(n + 1)!，c 在 a 與 x 之間","correct":true},{"label":"f⁽ⁿ⁺¹⁾(a)(x − a)ⁿ⁺¹/(n + 1)!","why":"那只是 Taylor 級數的下一項；餘項的導數是在某個未知的 c 取值。"},{"label":"f⁽ⁿ⁾(c)(x − a)ⁿ/n!","why":"階數少了一：Tₙ 已經用到 n 階，誤差由第 n + 1 階決定。"}]},{"ask":"估計 Tₙ(x) 的誤差時，M 應該是？","options":[{"label":"|f⁽ⁿ⁺¹⁾| 在 a 與 x 之間整段的一個上界","correct":true},{"label":"|f⁽ⁿ⁺¹⁾(a)|","why":"c 不一定是 a；M 要蓋住 c 可能落在的整段區間。"},{"label":"|f(x)| 的最大值","why":"餘項裡的是第 n + 1 階導數，不是函數本身。"}]},{"ask":"|Rₙ(1)| ≤ 3/(n + 1)!，要小於 10⁻³，最小的 n 是？","options":[{"label":"6","correct":true},{"label":"5","why":"n = 5 時上界是 3/6! = 3/720 ≈ 0.0042，還大於 0.001。"},{"label":"7","why":"n = 6 時 3/7! ≈ 0.0006 已經 < 0.001，7 不是最小。"}]},{"ask":"Taylor 不等式給出的上界跟實際誤差的關係是？","options":[{"label":"實際誤差 ≤ 上界，通常小一些","correct":true},{"label":"兩者相等","why":"上界是把 c 換成最壞情況得到的，一般會比實際誤差大，例如 sin 1 的 0.035 對 0.0081。"},{"label":"實際誤差可能比上界大","why":"那就不叫上界了；只要 M 真的蓋住整段區間，實際誤差一定不超過它。"}]}],"practice":[{"id":"tr-bnd-001","core":true},{"id":"tr-bnd-003","core":true},{"id":"lec-15-q1c","core":true},{"id":"lec-15-q4d","core":true},{"id":"tr-err-001","core":true},{"id":"tr-bnd-002"},{"id":"tr-bnd-005"},{"id":"tr-err-002"},{"id":"tr-num-005"},{"id":"tr-num-001"},{"id":"tr-bnd-009"},{"id":"lec-15-q3b"},{"id":"tr-num-003","challenge":true,"note":"挑戰：sin x 的多項式只有奇次項，要注意 Tₙ 與 Tₙ₊₁ 相同時可以用更高一階的導數估計。"}]},"taylor-limits":{"id":"taylor-limits","prerequisites":["maclaurin-series","taylor-error"],"next":["parametric-curves"],"related":["lhopital","taylor-limits-higher","big-o-little-o"],"objectives":["把 x → 0 的 0/0 極限裡每個函數換成「Maclaurin 多項式 + o(xⁿ)」，消去之後讀出第一個留下的項。","看分母的次方決定分子要展到第幾階。","會用 o(xⁿ) 的三條基本規則，並知道這樣做為什麼合法。"],"concept":[{"heading":"① 想法：在 0 附近，函數就是多項式","body":["x 很靠近 0 時，sin x = x − x³/6 + （比 x³ 更小的東西）。把極限裡的每個函數都換成這種「多項式 + 更小的東西」，0/0 的分子分母會消掉一大片，第一個留下來的項就決定了極限。","例：(x − sin x)/x³ 的分子 = x − (x − x³/6 + …) = x³/6 + …，除以 x³ 得 1/6 + （→ 0 的東西），極限是 1/6。用〈L'Hôpital 法則〉要連續微分三次。"]},{"heading":"② 記號 o(xⁿ)","body":["o(xⁿ) 代表「除以 xⁿ 之後 → 0 的東西」（x → 0）。例如 x³ 是 o(x²)，因為 x³/x² = x → 0。三條夠用的規則：","o(xⁿ) ± o(xⁿ) 還是 o(xⁿ)；xᵏ · o(xⁿ) = o(x^{n+k})；比 n 高次的 xᵐ（m > n）都是 o(xⁿ)。","寫法：sin x = x − x³/6 + o(x³)，eˣ = 1 + x + x²/2 + o(x²)。更完整的規則在〈Big-O 與 little-o〉。"]},{"heading":"③ 要展到第幾階","body":["分母是 xᵏ，分子就要展到 xᵏ 那一項。展得不夠，分子會只剩 o(…)，看起來像 0/0，什麼都看不出來；展得太多不會錯，只是白算。","分母也是函數時（例如 1 − cos x），兩邊都展開到各自第一個不為 0 的項。"]},{"heading":"④ 為什麼可以這樣換","body":["〈Taylor 誤差〉說 f(x) = Tₙ(x) + Rₙ(x)，Rₙ(x) = f⁽ⁿ⁺¹⁾(c)xⁿ⁺¹/(n + 1)!。只要 f⁽ⁿ⁺¹⁾ 在 0 附近連續（五個基本函數都是），它在 0 附近就有界，所以 |Rₙ(x)| ≤ M|x|ⁿ⁺¹，Rₙ(x)/xⁿ → 0，也就是 Rₙ(x) = o(xⁿ)。這正是「多項式 + o(xⁿ)」的意思，不是近似，是等式。"]}],"workedExamples":[{"title":"展開一個函數","prompt":"lim_{x→0} (x − sin x)/x³","steps":["分母 x³，sin x 展到 x³：sin x = x − x³/6 + o(x³)。","分子 x − sin x = x³/6 + o(x³)。","(x³/6 + o(x³))/x³ = 1/6 + o(x³)/x³ → 1/6。"],"answer":"1/6"},{"title":"分子分母都展開","prompt":"lim_{x→0} (eˣ − 1 − x)/(1 − cos x)","problemId":"uni-lim-012","steps":["分子：eˣ = 1 + x + x²/2 + o(x²)，所以 eˣ − 1 − x = x²/2 + o(x²)。","分母：cos x = 1 − x²/2 + o(x²)，所以 1 − cos x = x²/2 + o(x²)。","分子分母同除以 x²：(1/2 + o(1))/(1/2 + o(1)) → 1。（o(1) 就是 o(x⁰)：趨近 0 的東西。）"],"answer":"1"},{"title":"代換後再展開","prompt":"lim_{x→0} (e^{x²} − cos x)/x²","problemId":"uni-lim-003","steps":["e^{x²}：把 eᵘ = 1 + u + o(u) 的 u 換成 x²，得 1 + x² + o(x²)。","cos x = 1 − x²/2 + o(x²)。","分子 = (1 + x²) − (1 − x²/2) + o(x²) = (3/2)x² + o(x²)。除以 x²，極限 3/2。"],"answer":"3/2"}],"pitfalls":["展得不夠深，分子只剩 o(…)，就誤判極限是 0。","係數忘了除以階乘：eˣ 的 x² 項是 x²/2。","o(x²) − o(x²) 寫成 0：兩個未知的小量相減還是 o(x²)，不是 0。","x → ∞ 或 x → a ≠ 0 時直接套 0 附近的展開（要先換變數）。"],"checks":[{"ask":"lim_{x→0} (ln(1 + x) − x)/x² = ？","options":[{"label":"−1/2","correct":true},{"label":"1/2","why":"ln(1 + x) = x − x²/2 + …，x² 項是負的。"},{"label":"0","why":"只展到 x + o(x) 的話，分子是 o(x)，跟 x² 比讀不出東西；要展到 x²。"}]},{"ask":"求 lim_{x→0} (sin x − x + x³/6)/x⁵，sin x 至少要展到？","options":[{"label":"x⁵ 項","correct":true},{"label":"x³ 項","why":"到 x³ 時分子全部消掉，只剩 o(x³)，除以 x⁵ 無法判斷。"},{"label":"x⁷ 項","why":"不會錯，但 x⁷ 項除以 x⁵ → 0，對答案沒有貢獻，是多餘的。"}]},{"ask":"x → 0 時，下列哪個是 o(x²)？","options":[{"label":"x³","correct":true},{"label":"x²","why":"x²/x² = 1，不趨近 0。"},{"label":"5x","why":"5x/x² = 5/x → ∞；5x 比 x² 大得多。"}]},{"ask":"lim_{x→0} (eˣ − 1 − x)/x² = ？","options":[{"label":"1/2","correct":true},{"label":"1","why":"eˣ 的 x² 係數是 1/2!，不是 1。"},{"label":"0","why":"eˣ 只展到 1 + x 會看不到 x² 項；展到 x² 才有 x²/2。"}]}],"practice":[{"id":"lim-024","core":true},{"id":"lec-15-q2b","core":true},{"id":"exam-lim-020","core":true},{"id":"mob-limtrap-005","core":true},{"id":"uni-lim-012","core":true},{"id":"lec-15-q2c"},{"id":"mob-limtrap-006"},{"id":"uni-lim-003"},{"id":"exam-lim-003"},{"id":"exam-lim-006"},{"id":"exam-lim-002"},{"id":"depth-lim-009"},{"id":"uni-lim-007"},{"id":"burst-boss-lim-002"},{"id":"uni-lim-010","challenge":true,"note":"挑戰：arctan x 與 arcsin x 的一次項相同，要各展到 x³：x − x³/3 與 x + x³/6。"}]}});
